export const USER_PINESCRIPT = "//@version=6\r\nindicator('all in one', 'all in ones', overlay = true, max_labels_count = 500, max_lines_count = 500, max_boxes_count = 1500,max_bars_back = 5000,precision = 2,format = format.price)\r\n// import TradingView/ta/10 (built-in in PineTS)\r\n// import jdehorty/KernelFunctions/2 as kernels\r\n\r\n\r\n//Height Control (applies to all 4 indicators below) - width/length is untouched\r\nHeightGroup = 'Height Control (All Indicators)'\r\nboxHeightScale = input.float(0.4, 'Box Height Scale', minval = 0.05, maxval = 1.0, step = 0.05, group = HeightGroup, tooltip = 'Shrinks the vertical height of every box toward its own midpoint. Lower = shorter boxes. Width/length is not affected.')\r\n\r\n\r\n// // new indicator: auto trendline doji emoji:\r\n\r\n// var int TYPE_UP = 1\r\n// var int TYPE_DOWN = -1\r\n// var string LINE_WIDTH1_STR = 'Width 1'\r\n// var string LINE_WIDTH2_STR = 'Width 2'\r\n// var string LINE_WIDTH6_STR = 'Width 6'\r\n// _get_width(string str_input) =>\r\n//     switch str_input // {string:int}\r\n//         LINE_WIDTH1_STR => 1\r\n//         LINE_WIDTH2_STR => 2\r\n//         LINE_WIDTH6_STR => 6\r\n\r\n// // ----------------------------------------------------------------------------\r\n// // Settings:\r\n// // {\r\n// var string GROUP_FRACT = 'Fractals'\r\n// var int n = input.int(10, title = 'Fractal Period', minval = 2, group = GROUP_FRACT)\r\n// var color col_hl = input.color(color.blue, title = 'Plot:', inline = 'plot_low', group = GROUP_FRACT)\r\n// var bool show_hl = input.bool(true, title = 'HL', inline = 'plot_low', group = GROUP_FRACT)\r\n// var color col_ll = input.color(color.gray, title = ', Plot:', inline = 'plot_low', group = GROUP_FRACT)\r\n// var bool show_ll = input.bool(false, title = 'LL', inline = 'plot_low', group = GROUP_FRACT)\r\n// var color col_lh = input.color(color.red, title = 'Plot:', inline = 'plot_high', group = GROUP_FRACT)\r\n// var bool show_lh = input.bool(true, title = 'LH', inline = 'plot_high', group = GROUP_FRACT)\r\n// var color col_hh = input.color(color.gray, title = ', Plot:', inline = 'plot_high', group = GROUP_FRACT)\r\n// var bool show_hh = input.bool(false, title = 'HH', inline = 'plot_high', group = GROUP_FRACT)\r\n\r\n// var string GROUP_ATL = 'Auto trendlines'\r\n// var string subgroup1 = 'recent line'\r\n// var color ln_col_recent = input.color(color.new(color.purple, 0), title = 'Recent Line', group = GROUP_ATL, inline = subgroup1)\r\n// var int lnwidth_recent = _get_width(input.string(LINE_WIDTH1_STR, options = [LINE_WIDTH1_STR, LINE_WIDTH2_STR, LINE_WIDTH6_STR], title = '', inline = subgroup1, group = GROUP_ATL))\r\n// var string subgroup2 = 'historical line'\r\n// var color ln_col_prev = input.color(color.new(color.gray, 50), title = 'Historical Line', group = GROUP_ATL, inline = subgroup2)\r\n// var int lnwidth_prev = _get_width(input.string(LINE_WIDTH1_STR, options = [LINE_WIDTH1_STR, LINE_WIDTH2_STR], title = '', inline = subgroup2, group = GROUP_ATL))\r\n\r\n// var int max_tl = input.int(1, title = 'Max pair of lines', maxval = 250, minval = 1, group = GROUP_ATL) * 2\r\n// var string _str_extend = input.string('Right', options = ['Right', 'Both ways'], title = 'Which way to extend lines', group = GROUP_ATL)\r\n// var string str_extend = _str_extend == 'Both ways' ? extend.both : extend.right\r\n\r\n// var bool show_crosses = input.bool(false, title = 'Show crosses', tooltip = 'Instances when closing price of a bar has crossed lower/upper trendlines', group = GROUP_ATL)\r\n// // }\r\n\r\n// // ----------------------------------------------------------------------------\r\n// // Fractal UDT and other relevant data structures: \r\n// // Handle fractals and trendlines associated with them\r\n// // {\r\n// type fractal\r\n// \tint up_or_down = na // either TYPE_UP or TYPE_DOWN\r\n// \tint xloc = na\r\n// \tfloat yloc = na\r\n// \tint xloc_parent = na\r\n// \tfloat yloc_parent = na\r\n\r\n// var array<fractal> arr_fract = array.new<fractal>() // Can be used for multiple purposes such as:\r\n// // (a) connecting trendlines but added condition to skip X no. of fractals in between\r\n// // (b) create a zigzag, since knowing foo.parent's x and y\r\n// // ... possibilities are endless\r\n\r\n// var array<line> arr_ln_up = array.new_line() // Array of lines, newest elements inserted to front\r\n// var array<line> arr_ln_dn = array.new_line()\r\n\r\n// // @function init_fractal() returns instance of fractal that has been init'ed\r\n// init_fractal(int fract_type, int xloc, float yloc, int xparent, float yparent) =>\r\n//     f = fractal.new()\r\n//     f.up_or_down := fract_type\r\n//     f.xloc := xloc\r\n//     f.yloc := yloc\r\n//     f.xloc_parent := xparent\r\n//     f.yloc_parent := yparent\r\n\r\n//     ln = line.new(xloc, yloc, xparent, yparent, xloc.bar_index, str_extend, color = ln_col_recent, style = line.style_solid, width = lnwidth_recent)\r\n//     if f.up_or_down == TYPE_UP\r\n//         array.unshift(arr_ln_up, ln)\r\n//     else if f.up_or_down == TYPE_DOWN\r\n//         array.unshift(arr_ln_dn, ln)\r\n\r\n//     array.unshift(arr_fract, f)\r\n//     f // <- return\r\n\r\n// // @function drop_and_roll(new fractal) returns void\r\n// // Clean up: Drop oldest trendlines, change colors for previous trendline\r\n// drop_and_roll(fractal f) =>\r\n//     arr_ln = f.up_or_down == TYPE_UP ? arr_ln_up : f.up_or_down == TYPE_DOWN ? arr_ln_dn : na\r\n//     if array.size(arr_ln) > 1\r\n//         line.set_color(array.get(arr_ln, 1), ln_col_prev)\r\n//         line.set_width(array.get(arr_ln, 1), lnwidth_prev)\r\n//         while array.size(arr_ln) > math.floor(max_tl / 2)\r\n//             line.delete(array.pop(arr_ln))\r\n\r\n// // @function draw_trendline() returns void\r\n// draw_trendline(fract_type, x2, y2, x1, y1) =>\r\n//     f = init_fractal(fract_type, x2, y2, x1, y1)\r\n//     drop_and_roll(f)\r\n\r\n// // } end of handle for fractals\r\n\r\n// // ----------------------------------------------------------------------------\r\n// // Fractals, implemented using ta.pivot high && low \r\n// // ----------------------------------------------------------------------------\r\n\r\n// // A Fractal is always a Pivot H/L (but a Pivot H/L is not always a Fractal):\r\n// float ph = ta.pivothigh(n, n)[1]\r\n// bool upfract = not na(ph)\r\n// float pl = ta.pivotlow(n, n)[1]\r\n// bool downfract = not na(pl)\r\n\r\n// alertcondition(not na(ph) or not na(pl), title = 'New trendline formed', message = 'New trendline formed')\r\n\r\n// // Pointers -> Recent fractals\r\n// // {\r\n// var float recent_dn1 = na\r\n// var int i_recent_dn1 = na\r\n// var float recent_up1 = na\r\n// var int i_recent_up1 = na\r\n// var float recent_dn2 = na\r\n// var int i_recent_dn2 = na\r\n// var float recent_up2 = na\r\n// var int i_recent_up2 = na\r\n\r\n// if downfract\r\n//     recent_dn2 := recent_dn1\r\n//     i_recent_dn2 := i_recent_dn1\r\n//     recent_dn1 := low[n + 1]\r\n//     i_recent_dn1 := bar_index - n - 1\r\n//     draw_trendline(TYPE_DOWN, i_recent_dn2, recent_dn2, i_recent_dn1, recent_dn1)\r\n\r\n// if upfract\r\n//     recent_up2 := recent_up1\r\n//     i_recent_up2 := i_recent_up1\r\n//     recent_up1 := high[n + 1]\r\n//     i_recent_up1 := bar_index - n - 1\r\n//     draw_trendline(TYPE_UP, i_recent_up2, recent_up2, i_recent_up1, recent_up1)\r\n\r\n// // }\r\n\r\n// // Plotting fractals\r\n// bool hh = bool(upfract and recent_up1 > recent_up2 ? high[n + 1] : na)\r\n// bool lh = bool(upfract and recent_up1 < recent_up2 ? high[n + 1] : na)\r\n// bool hl = bool(downfract and recent_dn1 > recent_dn2 ? low[n + 1] : na)\r\n// bool ll = bool(downfract and recent_dn1 < recent_dn2 ? low[n + 1] : na)\r\n\r\n// // plotshape(show_hh and hh, style = shape.circle, size = size.tiny, offset = -n - 1, title = 'HH', text = 'HH', location = location.abovebar, textcolor = col_hh, color = na, editable = false)\r\n// // plotshape(show_lh and lh, style = shape.circle, size = size.tiny, offset = -n - 1, title = 'LH', text = 'LH', location = location.abovebar, textcolor = col_lh, color = na, editable = false)\r\n// // plotshape(show_ll and ll, style = shape.circle, size = size.tiny, offset = -n - 1, title = 'LL', text = 'LL', location = location.belowbar, textcolor = col_ll, color = na, editable = false)\r\n// // plotshape(show_hl and hl, style = shape.circle, size = size.tiny, offset = -n - 1, title = 'HL', text = 'HL', location = location.belowbar, textcolor = col_hl, color = na, editable = false)\r\n\r\n// // ----------------------------------------------------------------------------\r\n// // Finding crosses between closing price & pair of most recent trendlines\r\n// // ----------------------------------------------------------------------------\r\n\r\n// // @function get_slope()\r\n// get_slope(xA, yA, xB, yB) =>\r\n//     (yB - yA) / (xB - xA)\r\n\r\n// // Solving for price at current x (bar_index), given two pairs of fractals with x values < bar_index.\r\n// float m_dn = get_slope(i_recent_dn1, recent_dn1, i_recent_dn2, recent_dn2)\r\n// float y_dn = m_dn * bar_index + recent_dn1 - m_dn * i_recent_dn1\r\n// float m_up = get_slope(i_recent_up1, recent_up1, i_recent_up2, recent_up2)\r\n// float y_up = m_up * bar_index + recent_up1 - m_up * i_recent_up1\r\n\r\n// // Plotting crosses\r\n// bool cross_upper = ta.cross(close, y_up)\r\n// bool cross_lower = ta.cross(close, y_dn)\r\n// plotshape(show_crosses and cross_upper, title = 'Crossed upper trendline', style = shape.xcross, location = location.belowbar, color = color.new(color = color.blue, transp = 50), size = size.small)\r\n// plotshape(show_crosses and cross_lower, title = 'Crossed lower trendline', style = shape.xcross, location = location.abovebar, color = color.new(color = color.red, transp = 20), size = size.small)\r\n\r\n// alertcondition(cross_upper or cross_lower, title = 'Upper/lower trendline crossed', message = 'Upper/lower trendline crossed')\r\n\r\n// new indicator: Volume Breakout Trading System: VBTS by ceyhun\r\n\r\n\r\nlength_volume_breakout_trading_system = input.int(20, 'length', minval = 1)\r\navrg_volume_breakout_trading_system = ta.sma(close, length_volume_breakout_trading_system)\r\nlength2_volume_breakout_trading_system = input.int(50, 'length', minval = 1)\r\navrg2_volume_breakout_trading_system = ta.sma(volume, length2_volume_breakout_trading_system)\r\n\r\nBuy_volume_breakout_trading_system = volume >= volume[1] * 1.5 and close > avrg_volume_breakout_trading_system and volume > avrg2_volume_breakout_trading_system\r\nSell_volume_breakout_trading_system = volume >= volume[1] * 1.5 and close < avrg_volume_breakout_trading_system and volume > avrg2_volume_breakout_trading_system\r\n\r\niff_1_volume_breakout_trading_system = close < avrg_volume_breakout_trading_system ? #FF3C3C: #000000\r\ncolors_volume_breakout_trading_system = close > avrg_volume_breakout_trading_system ? #55C6F7 : iff_1_volume_breakout_trading_system\r\n\r\nplot(avrg_volume_breakout_trading_system, title = 'SMA', color = colors_volume_breakout_trading_system, linewidth = 10)\r\n\r\n\r\n// NEW INDICATOR: Auto FibONACCI RETRACEMENT BY KIVANCOZBILGIC\r\n\r\nlen = input(144, 'Auto Fibo Length')\r\n\r\nhl1272a = input(1.272, 'Adjustable Fibo Level')\r\n\r\nAFL = input(false, title = 'Show Adjustable Fibo Level?')\r\nAFL1 = input(false, title = 'Show 1.618 Fibo Level?')\r\nAFL2 = input(false, title = 'Show 2.618 Fibo Level?')\r\nAFL3 = input(false, title = 'Show 3.618 Fibo Level?')\r\n\r\nh1 = ta.highest(high, len)\r\nl1 = ta.lowest(low, len)\r\nfark = h1 - l1\r\n\r\nhl236  = l1 + fark * 0.236\r\nhl382  = l1 + fark * 0.382\r\nhl500  = l1 + fark * 0.5\r\nhl618  = l1 + fark * 0.618\r\nhl786  = l1 + fark * 0.786\r\nhl1272 = l1 + fark * hl1272a\r\nhl1618 = l1 + fark * 1.618\r\nhl2618 = l1 + fark * 2.618\r\nhl3618 = l1 + fark * 3.618\r\n\r\nlh236  = h1 - fark * 0.236\r\nlh382  = h1 - fark * 0.382\r\nlh500  = h1 - fark * 0.5\r\nlh618  = h1 - fark * 0.618\r\nlh786  = h1 - fark * 0.786\r\nlh1272 = h1 - fark * hl1272a\r\nlh1618 = h1 - fark * 1.618\r\nlh2618 = h1 - fark * 2.618\r\nlh3618 = h1 - fark * 3.618\r\n\r\nhbars = -ta.highestbars(high, len)\r\nlbars = -ta.lowestbars(low, len)\r\n\r\nf236  = hbars > lbars ? hl236  : lh236\r\nf382  = hbars > lbars ? hl382  : lh382\r\nf500  = hbars > lbars ? hl500  : lh500\r\nf618  = hbars > lbars ? hl618  : lh618\r\nf786  = hbars > lbars ? hl786  : lh786\r\nf1272 = hbars > lbars ? hl1272 : lh1272\r\nf1618 = hbars > lbars ? hl1618 : lh1618\r\nf2618 = hbars > lbars ? hl2618 : lh2618\r\nf3618 = hbars > lbars ? hl3618 : lh3618\r\n\r\n// --- Draw solid horizontal lines using line.new + extend.right ---\r\nvar line lowLine  = na\r\nvar line highLine = na\r\n\r\nif barstate.islast\r\n    line.delete(lowLine)\r\n    line.delete(highLine)\r\n\r\n    lowLine  := line.new(bar_index - len, l1, bar_index, l1, extend = extend.right, color = color.rgb(0, 0, 0), width = 12, style = line.style_solid)\r\n    highLine := line.new(bar_index - len, h1, bar_index, h1, extend = extend.right, color = #000000, width = 12, style = line.style_solid)\r\n\r\n\r\n// new indicator: pivots traditional auto:\r\npivotTypeInput = input.string(title = 'Type', defval = 'Traditional', options = ['Traditional', 'Fibonacci', 'Woodie', 'Classic', 'DM', 'Camarilla'])\r\npivotAnchorInput = input.string(title = 'Pivots Timeframe', defval = 'Auto', options = ['Auto', 'Daily', 'Weekly', 'Monthly', 'Quarterly', 'Yearly', 'Biyearly', 'Triyearly', 'Quinquennially', 'Decennially'])\r\nmaxHistoricalPivotsInput = input.int(title = 'Number of Pivots Back', defval = 15, minval = 1, maxval = 200, display = display.data_window)\r\nisDailyBasedInput = input.bool(title = 'Use Daily-based Values', defval = true, display = display.data_window, tooltip = 'When this option is unchecked, Pivot Points will use intraday data while calculating on intraday charts. If Extended Hours are displayed on the chart, they will be taken into account during the pivot level calculation. If intraday OHLC values are different from daily-based values (normal for stocks), the pivot levels will also differ.')\r\nshowLabelsInput = input.bool(title = 'Show Labels', defval = true, group = 'labels', display = display.data_window)\r\nshowPricesInput = input.bool(title = 'Show Prices', defval = true, group = 'labels', display = display.data_window)\r\npositionLabelsInput = input.string('Left', 'Labels Position', options = ['Left', 'Right'], group = 'labels', display = display.data_window)\r\nlinewidthInput = input.int(title = 'Line Width', defval = 1, minval = 1, maxval = 100, group = 'levels', display = display.data_window)\r\n\r\nDEFAULT_COLOR = #FB8C00\r\npColorInput = input.color(DEFAULT_COLOR, 'P‏  ‏  ‏', inline = 'P', group = 'levels', display = display.data_window)\r\npShowInput = input.bool(true, '', inline = 'P', group = 'levels', display = display.data_window)\r\ns1ColorInput = input.color(DEFAULT_COLOR, 'S1', inline = 'S1/R1', group = 'levels', display = display.data_window)\r\ns1ShowInput = input.bool(true, '', inline = 'S1/R1', group = 'levels', display = display.data_window)\r\nr1ColorInput = input.color(DEFAULT_COLOR, '‏  ‏  ‏  ‏  ‏  ‏  ‏  ‏R1', inline = 'S1/R1', group = 'levels', display = display.data_window)\r\nr1ShowInput = input.bool(true, '', inline = 'S1/R1', group = 'levels', display = display.data_window)\r\ns2ColorInput = input.color(DEFAULT_COLOR, 'S2', inline = 'S2/R2', group = 'levels', display = display.data_window)\r\ns2ShowInput = input.bool(true, '', inline = 'S2/R2', group = 'levels', display = display.data_window)\r\nr2ColorInput = input.color(DEFAULT_COLOR, '‏  ‏  ‏  ‏  ‏  ‏  ‏  ‏R2', inline = 'S2/R2', group = 'levels', display = display.data_window)\r\nr2ShowInput = input.bool(true, '', inline = 'S2/R2', group = 'levels', tooltip = 'Not applicable to DM', display = display.data_window)\r\ns3ColorInput = input.color(DEFAULT_COLOR, 'S3', inline = 'S3/R3', group = 'levels', display = display.data_window)\r\ns3ShowInput = input.bool(true, '', inline = 'S3/R3', group = 'levels', display = display.data_window)\r\nr3ColorInput = input.color(DEFAULT_COLOR, '‏  ‏  ‏  ‏  ‏  ‏  ‏  ‏R3', inline = 'S3/R3', group = 'levels', display = display.data_window)\r\nr3ShowInput = input.bool(true, '', inline = 'S3/R3', group = 'levels', tooltip = 'Not applicable to DM', display = display.data_window)\r\ns4ColorInput = input.color(DEFAULT_COLOR, 'S4', inline = 'S4/R4', group = 'levels', display = display.data_window)\r\ns4ShowInput = input.bool(true, '', inline = 'S4/R4', group = 'levels', display = display.data_window)\r\nr4ColorInput = input.color(DEFAULT_COLOR, '‏  ‏  ‏  ‏  ‏  ‏  ‏  ‏R4', inline = 'S4/R4', group = 'levels', display = display.data_window)\r\nr4ShowInput = input.bool(true, '', inline = 'S4/R4', group = 'levels', tooltip = 'Not applicable to: Fibonacci, DM', display = display.data_window)\r\ns5ColorInput = input.color(DEFAULT_COLOR, 'S5', inline = 'S5/R5', group = 'levels', display = display.data_window)\r\ns5ShowInput = input.bool(true, '', inline = 'S5/R5', group = 'levels', display = display.data_window)\r\nr5ColorInput = input.color(DEFAULT_COLOR, '‏  ‏  ‏  ‏  ‏  ‏  ‏  ‏R5', inline = 'S5/R5', group = 'levels', display = display.data_window)\r\nr5ShowInput = input.bool(true, '', inline = 'S5/R5', group = 'levels', tooltip = 'Not applicable to: Fibonacci, Woodie, Classic, DM', display = display.data_window)\r\n\r\ntype graphicSettings\r\n\tstring levelName\r\n\tcolor levelColor\r\n\tbool showLevel\r\n\r\nvar graphicSettingsArray = array.from(graphicSettings.new(' P', pColorInput, pShowInput), graphicSettings.new('R1', r1ColorInput, r1ShowInput), graphicSettings.new('S1', s1ColorInput, s1ShowInput), graphicSettings.new('R2', r2ColorInput, r2ShowInput), graphicSettings.new('S2', s2ColorInput, s2ShowInput), graphicSettings.new('R3', r3ColorInput, r3ShowInput), graphicSettings.new('S3', s3ColorInput, s3ShowInput), graphicSettings.new('R4', r4ColorInput, r4ShowInput), graphicSettings.new('S4', s4ColorInput, s4ShowInput), graphicSettings.new('R5', r5ColorInput, r5ShowInput), graphicSettings.new('S5', s5ColorInput, s5ShowInput))\r\n\r\nautoAnchor = switch \r\n    timeframe.isintraday => timeframe.multiplier <= 15 ? '1D' : '1W'\r\n    timeframe.isdaily => '1M'\r\n    => '12M'\r\n\r\npivotTimeframe = switch pivotAnchorInput\r\n    'Auto' => autoAnchor\r\n    'Daily' => '1D'\r\n    'Weekly' => '1W'\r\n    'Monthly' => '1M'\r\n    'Quarterly' => '3M'\r\n    => '12M'\r\n\r\n//@variable The number of years in the selected Pivot period\r\npivotYearMultiplier = switch pivotAnchorInput\r\n    'Biyearly' => 2\r\n    'Triyearly' => 3\r\n    'Quinquennially' => 5\r\n    'Decennially' => 10\r\n    => 1\r\n\r\n//@variable The number of values in the pivots of the selected type\r\nnumOfPivotLevels = switch pivotTypeInput\r\n    'Traditional' => 11\r\n    'Camarilla' => 11\r\n    'Woodie' => 9\r\n    'Classic' => 9\r\n    'Fibonacci' => 7\r\n    'DM' => 3\r\n\r\ntype pivotGraphic\r\n\tline pivotLine\r\n\tlabel pivotLabel\r\n\r\nmethod delete(pivotGraphic graphic) =>\r\n    graphic.pivotLine.delete()\r\n    graphic.pivotLabel.delete()\r\n\r\nvar drawnGraphics = matrix.new<pivotGraphic>()\r\n\r\nlocalPivotTimeframeChange = timeframe.change(pivotTimeframe) and year % pivotYearMultiplier == 0\r\nsecurityPivotTimeframeChange = timeframe.change(timeframe.period) and year % pivotYearMultiplier == 0\r\n\r\npivotTimeframeChangeCounter(condition) =>\r\n    var count = 0\r\n    if condition and bar_index > 0\r\n        count := count + 1\r\n        count\r\n    count\r\n\r\nlocalPivots = ta.pivot_point_levels(pivotTypeInput, localPivotTimeframeChange)\r\nsecurityPivotPointsArray = ta.pivot_point_levels(pivotTypeInput, securityPivotTimeframeChange)\r\n\r\nsecurityTimeframe = timeframe.isintraday ? '1D' : timeframe.period\r\n[securityPivots, securityPivotCounter] = request.security(syminfo.tickerid, pivotTimeframe, [securityPivotPointsArray, pivotTimeframeChangeCounter(securityPivotTimeframeChange)], lookahead = barmerge.lookahead_on)\r\npivotPointsArray = isDailyBasedInput ? securityPivots : localPivots\r\n\r\n//@function Sets the ending points of the currently active pivots to `endTime`.\r\naffixOldPivots(endTime) =>\r\n    if drawnGraphics.rows() > 0\r\n        lastGraphics = drawnGraphics.row(drawnGraphics.rows() - 1)\r\n\r\n        for graphic in lastGraphics\r\n            graphic.pivotLine.set_x2(endTime)\r\n            if positionLabelsInput == 'Right'\r\n                graphic.pivotLabel.set_x(endTime)\r\n\r\n//@function Draws pivot lines and labels from `startTime` to the approximate end of the period.\r\ndrawNewPivots(startTime) =>\r\n\r\n    newGraphics = array.new<pivotGraphic>()\r\n\r\n    for [index, coord] in pivotPointsArray\r\n        levelSettings = graphicSettingsArray.get(index)\r\n        isReasonable = not na(coord) and coord > 0 and coord <= close * 5 and coord >= close * 0.1\r\n        if isReasonable and levelSettings.showLevel\r\n            lineEndTime = startTime + timeframe.in_seconds(pivotTimeframe) * 1000 * pivotYearMultiplier\r\n            pivotLine = line.new(startTime, coord, lineEndTime, coord, xloc = xloc.bar_time, color = levelSettings.levelColor, width = linewidthInput)\r\n            pivotLabel = label.new(x = positionLabelsInput == 'Left' ? startTime : lineEndTime, y = coord, text = (showLabelsInput ? levelSettings.levelName + ' ' : '') + (showPricesInput ? '(' + str.tostring(coord, format.mintick) + ')' : ''), style = positionLabelsInput == 'Left' ? label.style_label_right : label.style_label_left, textcolor = levelSettings.levelColor, color = #00000000, xloc = xloc.bar_time)\r\n\r\n            newGraphics.push(pivotGraphic.new(pivotLine, pivotLabel))\r\n\r\n    drawnGraphics.add_row(array_id = newGraphics)\r\n\r\n    if drawnGraphics.rows() > maxHistoricalPivotsInput\r\n        oldGraphics = drawnGraphics.remove_row(0)\r\n\r\n        for graphic in oldGraphics\r\n            graphic.delete()\r\n\r\n\r\nlocalPivotDrawConditionStatic = not isDailyBasedInput and localPivotTimeframeChange\r\nsecurityPivotDrawConditionStatic = isDailyBasedInput and securityPivotCounter != securityPivotCounter[1]\r\n\r\nvar isMultiYearly = array.from('Biyearly', 'Triyearly', 'Quinquennially', 'Decennially').includes(pivotAnchorInput)\r\nlocalPivotDrawConditionDeveloping = not isDailyBasedInput and time_close == time_close(pivotTimeframe) and not isMultiYearly\r\nsecurityPivotDrawConditionDeveloping = false\r\n\r\nif securityPivotDrawConditionStatic or localPivotDrawConditionStatic\r\n    affixOldPivots(time)\r\n    drawNewPivots(time)\r\n\r\n// If possible, draw pivots from the beginning of the chart if none were found\r\nvar FIRST_BAR_TIME = time\r\nif barstate.islastconfirmedhistory and drawnGraphics.columns() == 0\r\n\r\n    if not na(securityPivots) and securityPivotCounter > 0\r\n        if isDailyBasedInput\r\n            drawNewPivots(FIRST_BAR_TIME)\r\n        else\r\n            na\r\n    else\r\n        na\r\n\r\n// new indicator: LuxAlgo - Trendlines with breaks\r\nlength_trendline = input.int(14, 'Swing Detection Lookback')\r\nmult_trendline = input.float(1., 'Slope', minval = 0, step = .1)\r\ncalcMethod_trendline = input.string('Atr', 'Slope Calculation Method', options = ['Atr', 'Stdev', 'Linreg'])\r\nbackpaint_trendline = input(true, tooltip = 'Backpainting offset displayed elements in the past. Disable backpainting to see real time information returned by the indicator.')\r\n\r\n//Style\r\nupCss_trendline = input.color(color.teal, 'Up Trendline Color', group = 'Style')\r\ndnCss_trendline = input.color(color.red, 'Down Trendline Color', group = 'Style')\r\nshowExt_trendline = input(true, 'Show Extended Lines')\r\n\r\n//-----------------------------------------------------------------------------}\r\n//Calculations\r\n//-----------------------------------------------------------------------------{\r\nvar upper_trendline = 0.\r\nvar lower_trendline = 0.\r\nvar slope_ph_trendline = 0.\r\nvar slope_pl_trendline = 0.\r\n\r\nvar offset_trendline = backpaint_trendline ? length_trendline : 0\r\n\r\nn_trendline = bar_index\r\nsrc_trendline = close\r\n\r\nph_trendline = ta.pivothigh(length_trendline, length_trendline)\r\npl_trendline = ta.pivotlow(length_trendline, length_trendline)\r\n\r\n//Slope Calculation Method\r\nslope_trendline = switch calcMethod_trendline\r\n    'Atr' => ta.atr(length_trendline) / length_trendline * mult_trendline\r\n    'Stdev' => ta.stdev(src_trendline, length_trendline) / length_trendline * mult_trendline\r\n    'Linreg' => math.abs(ta.sma(src_trendline * n_trendline, length_trendline) - ta.sma(src_trendline, length_trendline) * ta.sma(n_trendline, length_trendline)) / ta.variance(n_trendline, length_trendline) / 2 * mult_trendline\r\n\r\n//Get slopes and calculate trendlines\r\nslope_ph_trendline := bool(ph_trendline) ? slope_trendline : slope_ph_trendline\r\nslope_pl_trendline := bool(pl_trendline) ? slope_trendline : slope_pl_trendline\r\n\r\nupper_trendline := bool(ph_trendline) ? ph_trendline : upper_trendline - slope_ph_trendline\r\nlower_trendline := bool(pl_trendline) ? pl_trendline : lower_trendline + slope_pl_trendline\r\n\r\nvar upos_trendline = 0\r\nvar dnos_trendline = 0\r\nupos_trendline := bool(ph_trendline) ? 0 : close > upper_trendline - slope_ph_trendline * length_trendline ? 1 : upos_trendline\r\ndnos_trendline := bool(pl_trendline) ? 0 : close < lower_trendline + slope_pl_trendline * length_trendline ? 1 : dnos_trendline\r\n\r\n//-----------------------------------------------------------------------------}\r\n//Extended Lines\r\n//-----------------------------------------------------------------------------{\r\nvar uptl_trendline = line.new(na, na, na, na, color = upCss_trendline, extend = extend.right, width = 4)\r\nvar dntl_trendline = line.new(na, na, na, na, color = #ff525200, extend = extend.right, width = 4)\r\n\r\nif bool(ph_trendline) and showExt_trendline\r\n    uptl_trendline.set_xy1(n_trendline - offset_trendline, backpaint_trendline ? ph_trendline : upper_trendline - slope_ph_trendline * length_trendline)\r\n    uptl_trendline.set_xy2(n_trendline - offset_trendline + 1, backpaint_trendline ? ph_trendline - slope_trendline : upper_trendline - slope_ph_trendline * (length_trendline + 1))\r\n\r\nif bool(pl_trendline) and showExt_trendline\r\n    dntl_trendline.set_xy1(n_trendline - offset_trendline, backpaint_trendline ? pl_trendline : lower_trendline + slope_pl_trendline * length_trendline)\r\n    dntl_trendline.set_xy2(n_trendline - offset_trendline + 1, backpaint_trendline ? pl_trendline + slope_trendline : lower_trendline + slope_pl_trendline * (length_trendline + 1))\r\n\r\n//-----------------------------------------------------------------------------}\r\n//Plots\r\n//-----------------------------------------------------------------------------{\r\n// plot(backpaint_trendline ? upper_trendline : upper_trendline - slope_ph_trendline * length_trendline, 'Upper', color = bool(ph_trendline) ? na : upCss_trendline, offset = -offset_trendline, linewidth = 50)\r\n// plot(backpaint_trendline ? lower_trendline : lower_trendline + slope_pl_trendline * length_trendline, 'Lower', color = bool(pl_trendline) ? na : dnCss_trendline, offset = -offset_trendline, linewidth = 50)\r\n\r\n//Breakouts\r\nplotshape(upos_trendline > upos_trendline[1] ? low : na, 'Upper Break', shape.labelup, location.absolute, upCss_trendline, text = 'B', textcolor = color.white, size = size.tiny)\r\n\r\nplotshape(dnos_trendline > dnos_trendline[1] ? high : na, 'Lower Break', shape.labeldown, location.absolute, dnCss_trendline, text = 'B', textcolor = color.white, size = size.tiny)\r\n// new indicator: price actions volumetric ulgo\r\nswingLength__price_action = input.int(8, title = 'Swing Length', group = 'Price Action Volumetric Order Blocks [UAlgo] Settings')\r\nshowLastXOb__price_action = input.int(4, title = 'Show Last X Order Blocks', minval = 1, maxval = 10, group = 'Price Action Volumetric Order Blocks [UAlgo] Settings')\r\nviolationType__price_action = input.string('Wick', title = 'Violation Check', options = ['Wick', 'Close'], group = 'Price Action Volumetric Order Blocks [UAlgo] Settings')\r\nhideOverlap__price_action = input.string('True', title = 'Hide Overlap', options = ['True', 'False'], group = 'Price Action Volumetric Order Blocks [UAlgo] Settings')\r\nupObColor__price_action = input.color(color.rgb(0, 137, 123), title = 'Colors', group = 'Price Action Volumetric Order Blocks [UAlgo] Settings', inline = 'vs')\r\ndownObColor__price_action = input.color(#FF8A00, title = ' ', group = 'Price Action Volumetric Order Blocks [UAlgo] Settings', inline = 'vs')\r\n\r\ntype swing__price_action\r\n\tfloat y__price_action = na\r\n\tint x__price_action = na\r\n\tbool crossed__price_action = false\r\n\r\ntype ob__price_action\r\n\tfloat top__price_action = na\r\n\tfloat btm__price_action = na\r\n\tint barStart__price_action\r\n\tfloat bullishStr__price_action\r\n\tfloat bearishStr__price_action\r\n\tbox obBox__price_action\r\n\tbox bullishBox__price_action\r\n\tbox bearishBox__price_action\r\n\tfloat vol__price_action\r\n\tbool broken__price_action\r\n\tline seperatorLine__price_action\r\n\tline orderTextSeperator__price_action\r\n\r\ntype market__price_action\r\n\tstring msbOrBos__price_action\r\n\tint direction__price_action\r\n\tline marketLine__price_action\r\n\tint lastLineTime__price_action\r\n\tlabel marketLabel__price_action\r\n\r\nvar array<ob__price_action> bullishOb__price_action = array.new<ob__price_action>()\r\nvar array<ob__price_action> bearishOb__price_action = array.new<ob__price_action>()\r\nvar market__price_action marketStructure__price_action = market__price_action.new(na, na, na, 0)\r\n\r\nvar float top__price_action = na\r\nvar float btm__price_action = na\r\ntop__price_action := ta.pivothigh(swingLength__price_action, swingLength__price_action)\r\nbtm__price_action := ta.pivotlow(swingLength__price_action, swingLength__price_action)\r\n\r\n\r\nvar swing__price_action topp__price_action = swing__price_action.new()\r\nvar swing__price_action btmm__price_action = swing__price_action.new()\r\nif not na(top__price_action)\r\n    topp__price_action.x__price_action := time[swingLength__price_action]\r\n    topp__price_action.y__price_action := high[swingLength__price_action]\r\n    topp__price_action.crossed__price_action := false\r\n    topp__price_action.crossed__price_action\r\n\r\nif not na(btm__price_action)\r\n    btmm__price_action.x__price_action := time[swingLength__price_action]\r\n    btmm__price_action.y__price_action := low[swingLength__price_action]\r\n    btmm__price_action.crossed__price_action := false\r\n    btmm__price_action.crossed__price_action\r\n\r\ncalculateStrengths__price_action(barIndex__price_action) =>\r\n    float bullishStrength__price_action = 0.0\r\n    float bearishStrength__price_action = 0.0\r\n    int barsToConsider__price_action = swingLength__price_action\r\n\r\n    for i__price_action = 0 to barsToConsider__price_action - 1 by 1\r\n        if barIndex__price_action - i__price_action >= 0\r\n            float openn__price_action = open[barIndex__price_action - i__price_action]\r\n            float highh__price_action = high[barIndex__price_action - i__price_action]\r\n            float loww__price_action = low[barIndex__price_action - i__price_action]\r\n            float closee__price_action = close[barIndex__price_action - i__price_action]\r\n            float volumee__price_action = volume[barIndex__price_action - i__price_action]\r\n\r\n            if openn__price_action > closee__price_action\r\n                bearishStrength__price_action := bearishStrength__price_action + volumee__price_action\r\n                bearishStrength__price_action\r\n            else\r\n                bullishStrength__price_action := bullishStrength__price_action + volumee__price_action\r\n                bullishStrength__price_action\r\n\r\n    [bullishStrength__price_action, bearishStrength__price_action]\r\n\r\nisOverlapping__price_action(newBlock__price_action, existingArray__price_action) =>\r\n    bool flag__price_action = false\r\n    if existingArray__price_action.size() > 0\r\n        for i__price_action = 0 to existingArray__price_action.size() - 1 by 1\r\n            existingBlock__price_action = array.get(existingArray__price_action, i__price_action)\r\n            if newBlock__price_action.top__price_action >= existingBlock__price_action.btm__price_action and newBlock__price_action.top__price_action <= existingBlock__price_action.top__price_action or newBlock__price_action.btm__price_action >= existingBlock__price_action.btm__price_action and newBlock__price_action.btm__price_action <= existingBlock__price_action.top__price_action\r\n                flag__price_action := true\r\n                flag__price_action\r\n    flag__price_action\r\n\r\ndrawBox__price_action(volatilityBlock__price_action) =>\r\n    // Height Scale: compress top/btm toward the block's own midpoint (width/x-values untouched)\r\n    float midH__price_action = (volatilityBlock__price_action.top__price_action + volatilityBlock__price_action.btm__price_action) / 2\r\n    float scaledTop__price_action = midH__price_action + (volatilityBlock__price_action.top__price_action - midH__price_action) * boxHeightScale\r\n    float scaledBtm__price_action = midH__price_action - (midH__price_action - volatilityBlock__price_action.btm__price_action) * boxHeightScale\r\n    volatilityBlock__price_action.bullishBox__price_action := box.new(left = volatilityBlock__price_action.barStart__price_action, right = time, top = scaledTop__price_action, bottom = scaledBtm__price_action + (scaledTop__price_action - scaledBtm__price_action) / 2, bgcolor = color.new(upObColor__price_action, 0), border_color = na, xloc = xloc.bar_time)\r\n    volatilityBlock__price_action.bearishBox__price_action := box.new(left = volatilityBlock__price_action.barStart__price_action, right = time, top = scaledBtm__price_action + (scaledTop__price_action - scaledBtm__price_action) / 2, bottom = scaledBtm__price_action, bgcolor = color.new(downObColor__price_action, 0), border_color = na, xloc = xloc.bar_time)\r\n    volatilityBlock__price_action.obBox__price_action := box.new(left = volatilityBlock__price_action.barStart__price_action, right = time, top = scaledTop__price_action, bottom = scaledBtm__price_action, bgcolor = color.new(color.gray, 80), border_color = na, xloc = xloc.bar_time)\r\n    volatilityBlock__price_action.seperatorLine__price_action := line.new(x1 = volatilityBlock__price_action.barStart__price_action, y1 = scaledBtm__price_action + (scaledTop__price_action - scaledBtm__price_action) / 2, x2 = time, y2 = scaledBtm__price_action + (scaledTop__price_action - scaledBtm__price_action) / 2, color = color.new(color.gray, 50), width = 1, xloc = xloc.bar_time, style = line.style_dashed)\r\n    volatilityBlock__price_action.orderTextSeperator__price_action := line.new(x1 = volatilityBlock__price_action.barStart__price_action, y1 = scaledTop__price_action, x2 = volatilityBlock__price_action.barStart__price_action, y2 = scaledBtm__price_action, color = color.new(color.gray, 50), xloc = xloc.bar_time, style = line.style_solid)\r\n    volatilityBlock__price_action.top__price_action := scaledTop__price_action\r\n    volatilityBlock__price_action.btm__price_action := scaledBtm__price_action\r\n    volatilityBlock__price_action.orderTextSeperator__price_action\r\n\r\nif close < btmm__price_action.y__price_action and btmm__price_action.crossed__price_action == false\r\n    btmm__price_action.crossed__price_action := true\r\n    marketStructure__price_action.msbOrBos__price_action := na(marketStructure__price_action.msbOrBos__price_action) ? 'msb' : marketStructure__price_action.direction__price_action == -1 ? 'bos' : 'msb'\r\n    marketStructure__price_action.direction__price_action := -1\r\n    lineColor__price_action = color.red\r\n    marketStructure__price_action.marketLine__price_action := line.new(x1 = btmm__price_action.x__price_action, y1 = btmm__price_action.y__price_action, x2 = time, y2 = btmm__price_action.y__price_action, xloc = xloc.bar_time, color = lineColor__price_action)\r\n    marketStructure__price_action.lastLineTime__price_action := btmm__price_action.x__price_action\r\n    labelText__price_action = marketStructure__price_action.msbOrBos__price_action == 'msb' ? 'MSB' : 'BOS'\r\n    labelX__price_action = math.round(math.avg(btmm__price_action.x__price_action, time))\r\n    marketStructure__price_action.marketLabel__price_action := label.new(x = labelX__price_action, y = btmm__price_action.y__price_action, text = labelText__price_action, color = color.new(color.white, 100), textcolor = lineColor__price_action, style = label.style_label_up, xloc = xloc.bar_time, size = size.tiny)\r\n\r\n    float highAndGreenTop__price_action = 0\r\n    float highAndGreenBtm__price_action = 0\r\n    int highAndGreenTime__price_action = 0\r\n    int selectedIndex__price_action = 0\r\n    float vol__price_action = na\r\n    for i__price_action = 1 to swingLength__price_action by 1\r\n        if close[i__price_action] > open[i__price_action] and high[i__price_action] > highAndGreenTop__price_action\r\n            highAndGreenTop__price_action := high[i__price_action]\r\n            highAndGreenBtm__price_action := low[i__price_action]\r\n            highAndGreenTime__price_action := time[i__price_action]\r\n            vol__price_action := volume[i__price_action]\r\n            selectedIndex__price_action := i__price_action\r\n            selectedIndex__price_action\r\n\r\n    [bullishStrength__price_action, bearishStrength__price_action] = calculateStrengths__price_action(selectedIndex__price_action)\r\n\r\n    newOb__price_action = ob__price_action.new(highAndGreenTop__price_action, highAndGreenBtm__price_action, highAndGreenTime__price_action)\r\n    newOb__price_action.bullishStr__price_action := bullishStrength__price_action\r\n    newOb__price_action.bearishStr__price_action := bearishStrength__price_action\r\n    newOb__price_action.vol__price_action := vol__price_action\r\n    newOb__price_action.broken__price_action := false\r\n\r\n    if not isOverlapping__price_action(newOb__price_action, bearishOb__price_action) and hideOverlap__price_action == 'True'\r\n        array.push(bearishOb__price_action, newOb__price_action)\r\n        drawBox__price_action(newOb__price_action)\r\n    if hideOverlap__price_action == 'False'\r\n        array.push(bearishOb__price_action, newOb__price_action)\r\n        drawBox__price_action(newOb__price_action)\r\n\r\n    if array.size(bearishOb__price_action) > showLastXOb__price_action\r\n        oldOb__price_action = array.shift(bearishOb__price_action)\r\n        box.delete(oldOb__price_action.bullishBox__price_action)\r\n        box.delete(oldOb__price_action.bearishBox__price_action)\r\n        box.delete(oldOb__price_action.obBox__price_action)\r\n        line.delete(oldOb__price_action.seperatorLine__price_action)\r\n        line.delete(oldOb__price_action.orderTextSeperator__price_action)\r\n\r\nelse if close > topp__price_action.y__price_action and topp__price_action.crossed__price_action == false\r\n    topp__price_action.crossed__price_action := true\r\n    marketStructure__price_action.msbOrBos__price_action := na(marketStructure__price_action.msbOrBos__price_action) ? 'msb' : marketStructure__price_action.direction__price_action == 1 ? 'bos' : 'msb'\r\n    marketStructure__price_action.direction__price_action := 1\r\n    lineColor__price_action = color.green\r\n    marketStructure__price_action.marketLine__price_action := line.new(x1 = topp__price_action.x__price_action, y1 = topp__price_action.y__price_action, x2 = time, y2 = topp__price_action.y__price_action, xloc = xloc.bar_time, color = lineColor__price_action)\r\n    marketStructure__price_action.lastLineTime__price_action := topp__price_action.x__price_action\r\n    labelText__price_action = marketStructure__price_action.msbOrBos__price_action == 'msb' ? 'MSB' : 'BOS'\r\n    labelX__price_action = math.round(math.avg(topp__price_action.x__price_action, time))\r\n    marketStructure__price_action.marketLabel__price_action := label.new(x = labelX__price_action, y = topp__price_action.y__price_action, text = labelText__price_action, color = color.new(color.white, 100), textcolor = lineColor__price_action, style = label.style_label_down, xloc = xloc.bar_time, size = size.tiny)\r\n\r\n    float lowAndRedBtm__price_action = 999999999999\r\n    float lowAndRedTop__price_action = na\r\n    int lowAndRedTime__price_action = 0\r\n    int selectedIndex__price_action = 0\r\n    float vol__price_action = na\r\n    for i__price_action = 1 to swingLength__price_action by 1\r\n        if close[i__price_action] < open[i__price_action] and low[i__price_action] < lowAndRedBtm__price_action\r\n            lowAndRedBtm__price_action := low[i__price_action]\r\n            lowAndRedTop__price_action := high[i__price_action]\r\n            lowAndRedTime__price_action := time[i__price_action]\r\n            vol__price_action := volume[i__price_action]\r\n            selectedIndex__price_action := i__price_action\r\n            selectedIndex__price_action\r\n\r\n    [bullishStrength__price_action, bearishStrength__price_action] = calculateStrengths__price_action(selectedIndex__price_action)\r\n\r\n    newOb__price_action = ob__price_action.new(lowAndRedTop__price_action, lowAndRedBtm__price_action, lowAndRedTime__price_action)\r\n    newOb__price_action.bullishStr__price_action := bullishStrength__price_action\r\n    newOb__price_action.bearishStr__price_action := bearishStrength__price_action\r\n    newOb__price_action.vol__price_action := vol__price_action\r\n    newOb__price_action.broken__price_action := false\r\n\r\n    if not isOverlapping__price_action(newOb__price_action, bullishOb__price_action) and hideOverlap__price_action == 'True'\r\n        array.push(bullishOb__price_action, newOb__price_action)\r\n        drawBox__price_action(newOb__price_action)\r\n    if hideOverlap__price_action == 'False'\r\n        array.push(bullishOb__price_action, newOb__price_action)\r\n        drawBox__price_action(newOb__price_action)\r\n\r\n    if array.size(bullishOb__price_action) > showLastXOb__price_action\r\n        oldOb__price_action = array.shift(bullishOb__price_action)\r\n        box.delete(oldOb__price_action.bullishBox__price_action)\r\n        box.delete(oldOb__price_action.bearishBox__price_action)\r\n        box.delete(oldOb__price_action.obBox__price_action)\r\n        line.delete(oldOb__price_action.seperatorLine__price_action)\r\n        line.delete(oldOb__price_action.orderTextSeperator__price_action)\r\n\r\nif array.size(bullishOb__price_action) > 0\r\n    for i__price_action = 0 to array.size(bullishOb__price_action) - 1 by 1\r\n        currentOb__price_action = array.get(bullishOb__price_action, i__price_action)\r\n        totalStr__price_action = currentOb__price_action.bullishStr__price_action + currentOb__price_action.bearishStr__price_action\r\n        bullishBoxWidth__price_action = currentOb__price_action.bullishStr__price_action / totalStr__price_action * ((currentOb__price_action.obBox__price_action.get_left() + time) / 2 - currentOb__price_action.barStart__price_action)\r\n        bearishBoxWidth__price_action = currentOb__price_action.bearishStr__price_action / totalStr__price_action * ((currentOb__price_action.obBox__price_action.get_left() + time) / 2 - currentOb__price_action.barStart__price_action)\r\n        currentOb__price_action.bullishBox__price_action.set_right(math.round(currentOb__price_action.barStart__price_action + bullishBoxWidth__price_action))\r\n        currentOb__price_action.bearishBox__price_action.set_right(math.round(currentOb__price_action.barStart__price_action + bearishBoxWidth__price_action))\r\n        currentOb__price_action.obBox__price_action.set_right(time)\r\n        line.set_xy2(currentOb__price_action.seperatorLine__price_action, (currentOb__price_action.obBox__price_action.get_left() + time) / 2, currentOb__price_action.btm__price_action + (currentOb__price_action.top__price_action - currentOb__price_action.btm__price_action) / 2)\r\n\r\n        line.set_xy1(currentOb__price_action.orderTextSeperator__price_action, (currentOb__price_action.obBox__price_action.get_left() + time) / 2, currentOb__price_action.top__price_action)\r\n        line.set_xy2(currentOb__price_action.orderTextSeperator__price_action, (currentOb__price_action.obBox__price_action.get_left() + time) / 2, currentOb__price_action.btm__price_action)\r\n\r\n        violation__price_action = violationType__price_action == 'Wick' and low < currentOb__price_action.btm__price_action or violationType__price_action == 'Close' and close < currentOb__price_action.btm__price_action\r\n\r\n        if violation__price_action\r\n            box.delete(currentOb__price_action.bullishBox__price_action)\r\n            box.delete(currentOb__price_action.bearishBox__price_action)\r\n            box.delete(currentOb__price_action.obBox__price_action)\r\n            line.delete(currentOb__price_action.seperatorLine__price_action)\r\n            line.delete(currentOb__price_action.orderTextSeperator__price_action)\r\n            array.remove(bullishOb__price_action, i__price_action)\r\n            break\r\n\r\nif array.size(bearishOb__price_action) > 0\r\n    for i__price_action = 0 to array.size(bearishOb__price_action) - 1 by 1\r\n        currentOb__price_action = array.get(bearishOb__price_action, i__price_action)\r\n        totalStr__price_action = currentOb__price_action.bullishStr__price_action + currentOb__price_action.bearishStr__price_action\r\n        bullishBoxWidth__price_action = currentOb__price_action.bullishStr__price_action / totalStr__price_action * ((currentOb__price_action.obBox__price_action.get_left() + time) / 2 - currentOb__price_action.barStart__price_action)\r\n        bearishBoxWidth__price_action = currentOb__price_action.bearishStr__price_action / totalStr__price_action * ((currentOb__price_action.obBox__price_action.get_left() + time) / 2 - currentOb__price_action.barStart__price_action)\r\n        currentOb__price_action.bullishBox__price_action.set_right(math.round(currentOb__price_action.barStart__price_action + bullishBoxWidth__price_action))\r\n        currentOb__price_action.bearishBox__price_action.set_right(math.round(currentOb__price_action.barStart__price_action + bearishBoxWidth__price_action))\r\n        currentOb__price_action.obBox__price_action.set_right(time)\r\n        line.set_xy2(currentOb__price_action.seperatorLine__price_action, (currentOb__price_action.obBox__price_action.get_left() + time) / 2, currentOb__price_action.btm__price_action + (currentOb__price_action.top__price_action - currentOb__price_action.btm__price_action) / 2)\r\n\r\n        line.set_xy1(currentOb__price_action.orderTextSeperator__price_action, (currentOb__price_action.obBox__price_action.get_left() + time) / 2, currentOb__price_action.top__price_action)\r\n        line.set_xy2(currentOb__price_action.orderTextSeperator__price_action, (currentOb__price_action.obBox__price_action.get_left() + time) / 2, currentOb__price_action.btm__price_action)\r\n\r\n        violation__price_action = violationType__price_action == 'Wick' and high > currentOb__price_action.top__price_action or violationType__price_action == 'Close' and close > currentOb__price_action.top__price_action\r\n\r\n        if violation__price_action\r\n            box.delete(currentOb__price_action.bullishBox__price_action)\r\n            box.delete(currentOb__price_action.bearishBox__price_action)\r\n            box.delete(currentOb__price_action.obBox__price_action)\r\n            line.delete(currentOb__price_action.seperatorLine__price_action)\r\n            line.delete(currentOb__price_action.orderTextSeperator__price_action)\r\n            array.remove(bearishOb__price_action, i__price_action)\r\n            break\r\n\r\n\r\n\r\n//new indicator: smart money concepts:\r\n\r\n\r\n//-----------------------------------------------------------------------------}\r\n// CONSTANTS\r\n//-----------------------------------------------------------------------------{\r\nBULLISH_LEG  = 1\r\nBEARISH_LEG  = 0\r\nBULLISH      = +1\r\nBEARISH      = -1\r\n\r\nATR          = 'Atr'\r\nRANGE        = 'Cumulative Mean Range'\r\nCLOSE        = 'Close'\r\nHIGHLOW      = 'High/Low'\r\n\r\nBLOCKS_GROUP = 'Order Blocks'\r\n\r\n//-----------------------------------------------------------------------------}\r\n// INPUTS\r\n//-----------------------------------------------------------------------------{\r\nshowInternalOrderBlocksInput   = input(        true,       'Internal Order Blocks',   group = BLOCKS_GROUP, inline = 'iob')\r\ninternalOrderBlocksSizeInput   = input.int(    5,          '',                        group = BLOCKS_GROUP, minval = 1, maxval = 20, inline = 'iob')\r\nshowSwingOrderBlocksInput      = input(        true,       'Swing Order Blocks',      group = BLOCKS_GROUP, inline = 'ob')\r\nswingOrderBlocksSizeInput      = input.int(    5,          '',                        group = BLOCKS_GROUP, minval = 1, maxval = 20, inline = 'ob')\r\norderBlockFilterInput          = input.string( ATR,        'Order Block Filter',      group = BLOCKS_GROUP, options = [ATR, RANGE])\r\norderBlockMitigationInput      = input.string( HIGHLOW,    'Order Block Mitigation',  group = BLOCKS_GROUP, options = [CLOSE, HIGHLOW])\r\ninternalBullishOrderBlockColor = input.color(color.new(#3179f5, 80), 'Internal Bullish OB', group = BLOCKS_GROUP)\r\ninternalBearishOrderBlockColor = input.color(color.new(#f77c80, 80), 'Internal Bearish OB', group = BLOCKS_GROUP)\r\nswingBullishOrderBlockColor    = input.color(color.new(#1848cc, 80), 'Bullish OB',          group = BLOCKS_GROUP)\r\nswingBearishOrderBlockColor    = input.color(color.new(#b22833, 80), 'Bearish OB',          group = BLOCKS_GROUP)\r\n\r\nswingsLengthInput = input.int(50, 'Swing Detection Length', minval = 10)\r\n\r\n//-----------------------------------------------------------------------------}\r\n// DATA STRUCTURES\r\n//-----------------------------------------------------------------------------{\r\n// Pivot point\r\ntype pivot\r\n    float currentLevel\r\n    float lastLevel\r\n    bool  crossed\r\n    int   barTime  = time\r\n    int   barIndex = bar_index\r\n\r\n// Order block\r\ntype orderBlock\r\n    float barHigh\r\n    float barLow\r\n    int   barTime\r\n    int   bias\r\n\r\n// Trend bias wrapper (UDT fields are mutable inside functions, plain globals are not)\r\ntype trend\r\n    int bias\r\n\r\n//-----------------------------------------------------------------------------}\r\n// VARIABLES\r\n//-----------------------------------------------------------------------------{\r\nvar pivot swingHigh   = pivot.new(na, na, false)\r\nvar pivot swingLow    = pivot.new(na, na, false)\r\nvar pivot internalHigh = pivot.new(na, na, false)\r\nvar pivot internalLow  = pivot.new(na, na, false)\r\n\r\n// Trend bias instances (UDT fields can be mutated inside functions)\r\nvar trend internalTrend = trend.new(0)\r\nvar trend swingTrend    = trend.new(0)\r\n\r\n// Order block arrays\r\nvar array<orderBlock> swingOrderBlocks    = array.new<orderBlock>()\r\nvar array<orderBlock> internalOrderBlocks = array.new<orderBlock>()\r\n\r\n// Box arrays (pre-created for performance)\r\nvar array<box> swingOrderBlocksBoxes    = array.new<box>()\r\nvar array<box> internalOrderBlocksBoxes = array.new<box>()\r\n\r\n// Pre-create boxes on first bar\r\nif barstate.isfirst\r\n    if showSwingOrderBlocksInput\r\n        for i = 1 to swingOrderBlocksSizeInput\r\n            swingOrderBlocksBoxes.push(box.new(na, na, na, na, xloc = xloc.bar_time, extend = extend.right))\r\n    if showInternalOrderBlocksInput\r\n        for i = 1 to internalOrderBlocksSizeInput\r\n            internalOrderBlocksBoxes.push(box.new(na, na, na, na, xloc = xloc.bar_time, extend = extend.right))\r\n\r\n// Volatility / parsed high-low arrays\r\nvar array<float> parsedHighs = array.new<float>()\r\nvar array<float> parsedLows  = array.new<float>()\r\nvar array<float> highs       = array.new<float>()\r\nvar array<float> lows        = array.new<float>()\r\nvar array<int>   times       = array.new<int>()\r\n\r\natrMeasure       = ta.atr(200)\r\nvolatilityMeasure = orderBlockFilterInput == ATR ? atrMeasure : ta.cum(ta.tr) / bar_index\r\nhighVolatilityBar = (high - low) >= (2 * volatilityMeasure)\r\nparsedHigh        = highVolatilityBar ? low : high\r\nparsedLow         = highVolatilityBar ? high : low\r\n\r\nparsedHighs.push(parsedHigh)\r\nparsedLows.push(parsedLow)\r\nhighs.push(high)\r\nlows.push(low)\r\ntimes.push(time)\r\n\r\nbearishMitigationSrc = orderBlockMitigationInput == CLOSE ? close : high\r\nbullishMitigationSrc = orderBlockMitigationInput == CLOSE ? close : low\r\n\r\n//-----------------------------------------------------------------------------}\r\n// FUNCTIONS\r\n//-----------------------------------------------------------------------------{\r\n// Determine current leg direction\r\nleg(int size) =>\r\n    var int l = 0\r\n    if high[size] > ta.highest(size)\r\n        l := BEARISH_LEG\r\n    else if low[size] < ta.lowest(size)\r\n        l := BULLISH_LEG\r\n    l\r\n\r\nstartOfNewLeg(int l)     => ta.change(l) != 0\r\nstartOfBearishLeg(int l) => ta.change(l) == -1\r\nstartOfBullishLeg(int l) => ta.change(l) == +1\r\n\r\n// Store an order block from the pivot range\r\nstoreOrderBlock(pivot p_ivot, bool internal, int bias) =>\r\n    if (not internal and showSwingOrderBlocksInput) or (internal and showInternalOrderBlocksInput)\r\n        array<float> a_rray = na\r\n        int parsedIndex = na\r\n\r\n        if bias == BEARISH\r\n            a_rray      := parsedHighs.slice(p_ivot.barIndex, bar_index)\r\n            parsedIndex := p_ivot.barIndex + a_rray.indexof(a_rray.max())\r\n        else\r\n            a_rray      := parsedLows.slice(p_ivot.barIndex, bar_index)\r\n            parsedIndex := p_ivot.barIndex + a_rray.indexof(a_rray.min())\r\n\r\n        orderBlock ob              = orderBlock.new(parsedHighs.get(parsedIndex), parsedLows.get(parsedIndex), times.get(parsedIndex), bias)\r\n        array<orderBlock> obArray  = internal ? internalOrderBlocks : swingOrderBlocks\r\n\r\n        if obArray.size() >= 100\r\n            obArray.pop()\r\n        obArray.unshift(ob)\r\n\r\n// Remove mitigated order blocks\r\ndeleteOrderBlocks(bool internal) =>\r\n    array<orderBlock> obArray = internal ? internalOrderBlocks : swingOrderBlocks\r\n    for [i, ob] in obArray\r\n        bool crossed = false\r\n        if bearishMitigationSrc > ob.barHigh and ob.bias == BEARISH\r\n            crossed := true\r\n        else if bullishMitigationSrc < ob.barLow and ob.bias == BULLISH\r\n            crossed := true\r\n        if crossed\r\n            obArray.remove(i)\r\n\r\n// Draw order blocks as boxes\r\ndrawOrderBlocks(bool internal) =>\r\n    array<orderBlock> obArray = internal ? internalOrderBlocks : swingOrderBlocks\r\n    int obSize = obArray.size()\r\n    if obSize > 0\r\n        int maxOB              = internal ? internalOrderBlocksSizeInput : swingOrderBlocksSizeInput\r\n        array<orderBlock> parsed = obArray.slice(0, math.min(maxOB, obSize))\r\n        array<box> boxes       = internal ? internalOrderBlocksBoxes : swingOrderBlocksBoxes\r\n\r\n        for [i, ob] in parsed\r\n            color obColor =\r\n                 internal\r\n                 ? (ob.bias == BEARISH ? internalBearishOrderBlockColor : internalBullishOrderBlockColor)\r\n                 : (ob.bias == BEARISH ? swingBearishOrderBlockColor    : swingBullishOrderBlockColor)\r\n\r\n            // Height Scale: compress top/bottom toward the block's own midpoint (right edge/x-values untouched)\r\n            float midSMC = (ob.barHigh + ob.barLow) / 2\r\n            float scaledHighSMC = midSMC + (ob.barHigh - midSMC) * boxHeightScale\r\n            float scaledLowSMC  = midSMC - (midSMC - ob.barLow) * boxHeightScale\r\n\r\n            box b = boxes.get(i)\r\n            b.set_top_left_point(    chart.point.new(ob.barTime,    na, scaledHighSMC))\r\n            b.set_bottom_right_point(chart.point.new(last_bar_time, na, scaledLowSMC))\r\n            b.set_border_color(internal ? na : obColor)\r\n            b.set_bgcolor(obColor)\r\n\r\n// Track pivot points and trigger order block storage on structure breaks\r\ngetCurrentStructure(int size, bool internal) =>\r\n    int  currentLeg = leg(size)\r\n    bool newPivot   = startOfNewLeg(currentLeg)\r\n    bool pivotLow   = startOfBullishLeg(currentLeg)\r\n    bool pivotHigh  = startOfBearishLeg(currentLeg)\r\n\r\n    if newPivot\r\n        if pivotLow\r\n            pivot p = internal ? internalLow : swingLow\r\n            p.lastLevel    := p.currentLevel\r\n            p.currentLevel := low[size]\r\n            p.crossed      := false\r\n            p.barTime      := time[size]\r\n            p.barIndex     := bar_index[size]\r\n        else\r\n            pivot p = internal ? internalHigh : swingHigh\r\n            p.lastLevel    := p.currentLevel\r\n            p.currentLevel := high[size]\r\n            p.crossed      := false\r\n            p.barTime      := time[size]\r\n            p.barIndex     := bar_index[size]\r\n\r\n// Detect structure breaks and store order blocks accordingly\r\ndisplayStructure(bool internal) =>\r\n    pivot  ph = internal ? internalHigh : swingHigh\r\n    pivot  pl = internal ? internalLow  : swingLow\r\n    trend  t  = internal ? internalTrend : swingTrend\r\n\r\n    // Bullish break of structure\r\n    extraBull = internal ? internalHigh.currentLevel != swingHigh.currentLevel : true\r\n    if ta.crossover(close, ph.currentLevel) and not ph.crossed and extraBull\r\n        ph.crossed := true\r\n        t.bias     := BULLISH\r\n        if (internal and showInternalOrderBlocksInput) or (not internal and showSwingOrderBlocksInput)\r\n            storeOrderBlock(ph, internal, BULLISH)\r\n\r\n    // Bearish break of structure\r\n    extraBear = internal ? internalLow.currentLevel != swingLow.currentLevel : true\r\n    if ta.crossunder(close, pl.currentLevel) and not pl.crossed and extraBear\r\n        pl.crossed := true\r\n        t.bias     := BEARISH\r\n        if (internal and showInternalOrderBlocksInput) or (not internal and showSwingOrderBlocksInput)\r\n            storeOrderBlock(pl, internal, BEARISH)\r\n\r\n//-----------------------------------------------------------------------------}\r\n// EXECUTION\r\n//-----------------------------------------------------------------------------}\r\n// Track swing pivots (swing uses swingsLengthInput, internal uses 5)\r\ngetCurrentStructure(swingsLengthInput, false)\r\ngetCurrentStructure(5, true)\r\n\r\n// Detect breaks and store OBs\r\nif showInternalOrderBlocksInput or showSwingOrderBlocksInput\r\n    displayStructure(true)\r\n    displayStructure(false)\r\n\r\n// Mitigate crossed OBs\r\nif showInternalOrderBlocksInput\r\n    deleteOrderBlocks(true)\r\nif showSwingOrderBlocksInput\r\n    deleteOrderBlocks(false)\r\n\r\n// Draw on last confirmed / realtime bar\r\nif barstate.islastconfirmedhistory or barstate.islast\r\n    if showInternalOrderBlocksInput\r\n        drawOrderBlocks(true)\r\n    if showSwingOrderBlocksInput\r\n        drawOrderBlocks(false)\r\n\r\n\r\n// new indicator: pa toolkit lite (ualgo) :\r\n\r\nzigzagBool = input.bool(false, 'Show Market Structure', group = 'Price Action Toolkit Settings')\r\nzigzagLen = input.int(9, 'ZigZag Length', group = 'Price Action Toolkit Settings')\r\nliquidityBool = input.bool(true, 'Show Liquidity Sweeps', group = 'Liquidity Settings')\r\nliquidity_len = input.int(30, 'Liquidity Length', minval = 5, group = 'Liquidity Settings')\r\norderblockBool = input.bool(true, 'Show Order Blocks', group = 'Order Block Settings')\r\nnumberObShow = input.int(2, 'Number of Order Blocks to Show', group = 'Order Block Settings', minval = 1, maxval = 10)\r\nshowTrendLines = input.bool(true, 'Show Trend Lines', group = 'Misc')\r\ntrendLineLength = input.int(20, 'Trend Line Detection Sensitivity', group = 'Misc', minval = 10)\r\nupTlColor = input.color(color.new(color.teal, 15), title = 'Trend Line Colors', group = 'Misc', inline = 'tl')\r\ndownTlColor = input.color(color.new(color.red, 15), title = ' ', group = 'Misc', inline = 'tl')\r\nupColor = input.color(color.new(color.teal, 15), title = 'Market/Liquidity Colors', group = 'Visual Settings', inline = '1')\r\ndownColor = input.color(color.new(color.red, 15), title = ' ', group = 'Visual Settings', inline = '1')\r\nbearishOrderblockColor = input.color(color.new(color.red, 100), title = 'Order Block Colors ', group = 'Visual Settings', inline = '2')\r\nbullishOrderblockColor = input.color(color.new(#00bcd4, 80), title = ' ', group = 'Visual Settings', inline = '2')\r\nhideWatermark = input.bool(false, title = 'Hide Watermark', group = 'Visual Settings')\r\n\r\ntype orderblock\r\n\tfloat value\r\n\tint barStart\r\n\tint barEnd\r\n\tbox block\r\n\tbool broken\r\n\r\ntype liquidity\r\n\tfloat value\r\n\tint barStart\r\n\tint barEnd\r\n\tline liquidityLine\r\n\tbool broken\r\n\tlabel sweep\r\n\r\ntype zone\r\n\tfloat value\r\n\tint barStart\r\n\tint barEnd\r\n\tbox block\r\n\tstring zoneType\r\n\r\n\r\n\r\nvar array<orderblock> bullishOrderblock = array.new<orderblock>()\r\nvar array<orderblock> bearishOrderblock = array.new<orderblock>()\r\nvar array<liquidity> bullishLiquidity = array.new<liquidity>()\r\nvar array<liquidity> bearishLiquidity = array.new<liquidity>()\r\nvar array<int> highValIndex = array.new<int>()\r\nvar array<int> lowValIndex = array.new<int>()\r\nvar array<float> highVal = array.new_float()\r\nvar array<float> lowVal = array.new_float()\r\n\r\nvar bool drawUp = false\r\nvar bool drawDown = false\r\nvar string lastState = na\r\nvar bool to_up = false\r\nvar bool to_down = false\r\nvar int trend = 1\r\nvar float fibTopVal = na\r\nvar int fibTopIndex = na\r\nvar float fibBotVal = na\r\nvar int fibBotIndex = na\r\nvar float premiumVal = na\r\nvar float discountVal = na\r\nvar int premiumValIndex = na\r\nvar int discountValIndex = na\r\nvar box premiumBox = na\r\nvar box discountBox = na\r\nvar label premiumLabel = na\r\nvar label discountLabel = na\r\nvar string textOfPremium = na\r\nvar string textOfDiscount = na\r\nvar line newBearishTrendline = na\r\nvar line newBullishTrendline = na\r\n\r\natr = ta.atr(14)\r\n\r\nto_up := high[zigzagLen] >= ta.highest(high, zigzagLen)\r\nto_down := low[zigzagLen] <= ta.lowest(low, zigzagLen)\r\n\r\ntrend := trend == 1 and to_down ? -1 : trend == -1 and to_up ? 1 : trend\r\n\r\ndrawZigzag(x1, y1, x2, y2) =>\r\n    line.new(x1 = x1, y1 = y1, x2 = x2, y2 = y2, xloc = xloc.bar_time, width = 1)\r\n\r\nif ta.change(trend) != 0 and trend == 1\r\n    array.push(highValIndex, time[zigzagLen])\r\n    array.push(highVal, high[zigzagLen])\r\n    if array.size(lowVal) > 1\r\n        lastLowVal = array.get(lowVal, array.size(lowVal) - 1)\r\n        lastLowIndex = array.get(lowValIndex, array.size(lowValIndex) - 1)\r\n        lastHighIndex = array.get(highValIndex, array.size(highValIndex) - 1)\r\n        lastHighVal = array.get(highVal, array.size(highVal) - 1)\r\n        if zigzagBool\r\n            drawZigzag(x1 = lastLowIndex, y1 = lastLowVal, x2 = lastHighIndex, y2 = lastHighVal)\r\n        drawUp := false\r\n        drawUp\r\n    fibTopIndex := time[zigzagLen]\r\n    fibTopVal := high[zigzagLen]\r\n    fibTopVal\r\n\r\nif ta.change(trend) != 0 and trend == -1\r\n    array.push(lowValIndex, time[zigzagLen])\r\n    array.push(lowVal, low[zigzagLen])\r\n    if array.size(highVal) > 1\r\n        lastHighVal = array.get(highVal, array.size(highVal) - 1)\r\n        lastHighIndex = array.get(highValIndex, array.size(highValIndex) - 1)\r\n        lastLowIndex = array.get(lowValIndex, array.size(lowValIndex) - 1)\r\n        lastLowVal = array.get(lowVal, array.size(lowVal) - 1)\r\n        if zigzagBool\r\n            drawZigzag(x1 = lastHighIndex, y1 = lastHighVal, x2 = lastLowIndex, y2 = lastLowVal)\r\n        drawDown := false\r\n        drawDown\r\n    fibBotIndex := time[zigzagLen]\r\n    fibBotVal := low[zigzagLen]\r\n    fibBotVal\r\n\r\nif array.size(lowVal) > 1 and drawDown == false\r\n    if close < array.get(lowVal, array.size(lowVal) - 1)\r\n\r\n        line.new(x1 = array.get(lowValIndex, array.size(lowValIndex) - 1), y1 = array.get(lowVal, array.size(lowVal) - 1), x2 = time, y2 = array.get(lowVal, array.size(lowVal) - 1), width = 1, xloc = xloc.bar_time)\r\n        label.new(x = (array.get(lowValIndex, array.size(lowValIndex) - 1) + time) / 2, y = array.get(lowVal, array.size(lowVal) - 1), text = na(lastState) or lastState == 'up' ? 'CHoCH' : 'BoS', xloc = xloc.bar_time, style = label.style_label_up, textcolor = downColor, color = color.new(color.white, 100))\r\n        drawDown := true\r\n        lastState := 'down'\r\n        if orderblockBool\r\n            orderblock newOrderblock = orderblock.new()\r\n            float max = 0\r\n            int bar = na\r\n            \r\n            // --- FIX STARTS HERE ---\r\n            // 1. Get the previous time from your array\r\n            float prevTime = array.get(lowValIndex, array.size(lowValIndex) - 1)\r\n            \r\n            // 2. Calculate the duration of the current bar\r\n            float barDuration = time - time[1]\r\n            \r\n            // 3. Calculate how many bars ago that was\r\n            // We use math.floor to get an integer\r\n            int barsAgo = math.floor((time - prevTime - barDuration) / barDuration)\r\n            \r\n            // 4. CRITICAL STEP: Limit the lookback to 4900 to prevent crashing\r\n            // If the gap is bigger than 4900 bars, we stop at 4900.\r\n            int i_start = math.min(barsAgo, 4900)\r\n            \r\n            // Ensure it is not negative\r\n            i_start := math.max(i_start, 0)\r\n\r\n            // 5. Run the loop using the safe 'i_start' variable\r\n            for i = i_start to 0 by 1\r\n                if high[i] > max\r\n                    max := high[i]\r\n                    bar := time[i]\r\n            // --- FIX ENDS HERE ---\r\n\r\n            newOrderblock.barStart := bar\r\n            newOrderblock.barEnd := time\r\n            newOrderblock.broken := false\r\n            newOrderblock.value := max\r\n            newOrderblock.block := box.new(left = newOrderblock.barStart, top = newOrderblock.value - atr * boxHeightScale, right = newOrderblock.barEnd, bottom = newOrderblock.value, xloc = xloc.bar_time, bgcolor = bearishOrderblockColor, border_width = 1, border_color = bearishOrderblockColor)\r\n            array.push(bearishOrderblock, newOrderblock)\r\n            if array.size(bearishOrderblock) > 20\r\n                array.shift(bearishOrderblock)\r\n\r\nif array.size(highVal) > 1 and drawUp == false\r\n    if close > array.get(highVal, array.size(highVal) - 1)\r\n\r\n        line.new(x1 = array.get(highValIndex, array.size(highValIndex) - 1), y1 = array.get(highVal, array.size(highVal) - 1), x2 = time, y2 = array.get(highVal, array.size(highVal) - 1), width = 1, xloc = xloc.bar_time)\r\n        label.new(x = (array.get(highValIndex, array.size(highValIndex) - 1) + time) / 2, y = array.get(highVal, array.size(highVal) - 1), text = na(lastState) or lastState == 'down' ? 'CHoCH' : 'BoS', xloc = xloc.bar_time, style = label.style_label_down, textcolor = upColor, color = color.new(color.white, 100))\r\n        drawUp := true\r\n        lastState := 'up'\r\n        if orderblockBool\r\n            orderblock newOrderblock = orderblock.new()\r\n            float min = 999999999\r\n            int bar = na\r\n            for i = (time - array.get(highValIndex, array.size(highValIndex) - 1) - (time - time[1])) / (time - time[1]) to 0 by 1\r\n                if low[i] < min\r\n                    min := low[i]\r\n                    bar := time[i]\r\n                    bar\r\n\r\n            newOrderblock.barStart := bar\r\n            newOrderblock.barEnd := time\r\n            newOrderblock.broken := false\r\n            newOrderblock.value := min\r\n            newOrderblock.block := box.new(left = newOrderblock.barStart, top = newOrderblock.value + atr * boxHeightScale, right = newOrderblock.barEnd, bottom = newOrderblock.value, xloc = xloc.bar_time, bgcolor = bullishOrderblockColor, border_width = 1, border_color = bullishOrderblockColor)\r\n            array.push(bullishOrderblock, newOrderblock)\r\n            if array.size(bullishOrderblock) > 20\r\n                array.shift(bullishOrderblock)\r\n\r\n// Order block\r\n\r\n//update orderblock\r\nif array.size(bullishOrderblock) > 0\r\n    orderblock testOrderblock = na\r\n    int counter = 0\r\n    for i = array.size(bullishOrderblock) - 1 to 0 by 1\r\n        testOrderblock := array.get(bullishOrderblock, i)\r\n        if counter < numberObShow\r\n            testOrderblock.block.set_right(time)\r\n            if close < testOrderblock.value\r\n                testOrderblock.block.delete()\r\n                array.remove(bullishOrderblock, i)\r\n            counter := counter + 1\r\n            counter\r\n        else\r\n            testOrderblock.block.set_right(testOrderblock.barStart)\r\n\r\nif array.size(bearishOrderblock) > 0\r\n    orderblock testOrderblock = na\r\n    int counter = 0\r\n    for i = array.size(bearishOrderblock) - 1 to 0 by 1\r\n        testOrderblock := array.get(bearishOrderblock, i)\r\n        if counter < numberObShow\r\n            testOrderblock.block.set_right(time)\r\n            if close > testOrderblock.value\r\n                testOrderblock.block.delete()\r\n                array.remove(bearishOrderblock, i)\r\n            counter := counter + 1\r\n            counter\r\n        else\r\n            testOrderblock.block.set_right(testOrderblock.barStart)\r\n\r\n// Liquidity\r\n\r\nphLiquidity = ta.pivothigh(high, liquidity_len, liquidity_len)\r\nplLiquidity = ta.pivotlow(low, liquidity_len, liquidity_len)\r\n\r\nif not na(phLiquidity) and liquidityBool\r\n    liquidity newLiquidity = liquidity.new()\r\n    newLiquidity.value := high[liquidity_len]\r\n    newLiquidity.barStart := time[liquidity_len]\r\n    newLiquidity.barEnd := time\r\n    newLiquidity.broken := false\r\n    newLiquidity.liquidityLine := line.new(x1 = newLiquidity.barStart, y1 = newLiquidity.value, x2 = newLiquidity.barEnd, y2 = newLiquidity.value, xloc = xloc.bar_time, color = downColor, width = 1)\r\n    array.push(bearishLiquidity, newLiquidity)\r\n    if array.size(bearishLiquidity) > 7\r\n        deletedLiquidity = array.shift(bearishLiquidity)\r\n        deletedLiquidity.liquidityLine.delete()\r\n\r\nif not na(plLiquidity) and liquidityBool\r\n    liquidity newLiquidity = liquidity.new()\r\n    newLiquidity.value := low[liquidity_len]\r\n    newLiquidity.barStart := time[liquidity_len]\r\n    newLiquidity.barEnd := time\r\n    newLiquidity.broken := false\r\n    newLiquidity.liquidityLine := line.new(x1 = newLiquidity.barStart, y1 = newLiquidity.value, x2 = newLiquidity.barEnd, y2 = newLiquidity.value, xloc = xloc.bar_time, color = upColor, width = 1)\r\n    array.push(bullishLiquidity, newLiquidity)\r\n    if array.size(bullishLiquidity) > 7\r\n        deletedLiquidity = array.shift(bullishLiquidity)\r\n        deletedLiquidity.liquidityLine.delete()\r\n\r\n// Update liquidity\r\nif array.size(bearishLiquidity) > 0\r\n    liquidity testLiquidity = na\r\n    for i = array.size(bearishLiquidity) - 1 to 0 by 1\r\n        testLiquidity := array.get(bearishLiquidity, i)\r\n        if high > testLiquidity.value\r\n            testLiquidity.liquidityLine.set_x2(time)\r\n            testLiquidity.liquidityLine.set_style(line.style_dashed)\r\n            array.remove(bearishLiquidity, i)\r\n            if close < testLiquidity.value\r\n                testLiquidity.sweep := label.new(x = time, y = high, text = 'x', xloc = xloc.bar_time, style = label.style_label_down, size = size.normal, textcolor = color.new(color.purple, 0), color = color.new(color.white, 100))\r\n                testLiquidity.sweep\r\n\r\n        else\r\n            testLiquidity.liquidityLine.set_x2(time)\r\n\r\nif array.size(bullishLiquidity) > 0\r\n    liquidity testLiquidity = na\r\n    for i = array.size(bullishLiquidity) - 1 to 0 by 1\r\n        testLiquidity := array.get(bullishLiquidity, i)\r\n        if low < testLiquidity.value\r\n            testLiquidity.liquidityLine.set_x2(time)\r\n            testLiquidity.liquidityLine.set_style(line.style_dashed)\r\n            array.remove(bullishLiquidity, i)\r\n            if close > testLiquidity.value\r\n                testLiquidity.sweep := label.new(x = time, y = low, text = 'x', xloc = xloc.bar_time, style = label.style_label_up, size = size.normal, textcolor = color.new(color.teal, 0), color = color.new(color.white, 100))\r\n                testLiquidity.sweep\r\n\r\n        else\r\n            testLiquidity.liquidityLine.set_x2(time)\r\n\r\n//Watermark\r\n// if not hideWatermark\r\n//     var tableData = table.new(position = position.top_right, columns = 1, rows = 1, frame_color = color.orange, frame_width = 0)\r\n//     table.cell(tableData, 0, 0, 'UAlgo', text_color = color.new(color.orange, 0), text_size = size.large)\r\n\r\n// Trendlines\r\n\r\nextendTrendline(lineId, startIndex, startValue, endIndex, endValue) =>\r\n    slope = (endValue - startValue) / (endIndex - startIndex)\r\n    newEndIndex = bar_index\r\n    newEndValue = startValue + slope * (newEndIndex - startIndex)\r\n    line.set_x2(lineId, newEndIndex)\r\n    line.set_y2(lineId, newEndValue)\r\n\r\ngetSlope(startIndex, startValue, endIndex, endValue) =>\r\n    slope = (endValue - startValue) / (endIndex - startIndex)\r\n    slope\r\nif showTrendLines\r\n    phTrend = ta.pivothigh(high, trendLineLength, trendLineLength)\r\n    plTrend = ta.pivotlow(low, trendLineLength, trendLineLength)\r\n\r\n    bullishTrendLineStart = ta.valuewhen(not na(plTrend), bar_index[trendLineLength], 1)\r\n    bullishTrendLineEnd = ta.valuewhen(not na(plTrend), bar_index[trendLineLength], 0)\r\n    bearishTrendLineStart = ta.valuewhen(not na(phTrend), bar_index[trendLineLength], 1)\r\n    bearishTrendLineEnd = ta.valuewhen(not na(phTrend), bar_index[trendLineLength], 0)\r\n\r\n    bullishTrendLineStartVal = ta.valuewhen(not na(plTrend), low[trendLineLength], 1)\r\n    bullishTrendLineEndVal = ta.valuewhen(not na(plTrend), low[trendLineLength], 0)\r\n    bearishTrendLineStartVal = ta.valuewhen(not na(phTrend), high[trendLineLength], 1)\r\n    bearishTrendLineEndVal = ta.valuewhen(not na(phTrend), high[trendLineLength], 0)\r\n\r\n    line.delete(newBearishTrendline)\r\n    line.delete(newBullishTrendline)\r\n\r\n    slopeBearish = getSlope(bearishTrendLineStart, bearishTrendLineStartVal, bearishTrendLineEnd, bearishTrendLineEndVal)\r\n    slopeBullish = getSlope(bullishTrendLineStart, bullishTrendLineStartVal, bullishTrendLineEnd, bullishTrendLineEndVal)\r\n\r\n    // if slopeBearish < 0\r\n    //     newBearishTrendline := line.new(x1 = bearishTrendLineStart, y1 = bearishTrendLineStartVal, x2 = bar_index, y2 = bearishTrendLineEndVal, xloc = xloc.bar_index, color = downTlColor, width = 60)\r\n    //     newBearishTrendline\r\n    // if slopeBullish > 0\r\n    //     newBullishTrendline := line.new(x1 = bullishTrendLineStart, y1 = bullishTrendLineStartVal, x2 = bar_index, y2 = bullishTrendLineEndVal, xloc = xloc.bar_index, color = upTlColor, width = 60)\r\n    //     newBullishTrendline\r\n\r\n    // Extend the trendlines\r\n    if not na(newBearishTrendline)\r\n        extendTrendline(newBearishTrendline, bearishTrendLineStart, bearishTrendLineStartVal, bearishTrendLineEnd, bearishTrendLineEndVal)\r\n\r\n    if not na(newBullishTrendline)\r\n        extendTrendline(newBullishTrendline, bullishTrendLineStart, bullishTrendLineStartVal, bullishTrendLineEnd, bullishTrendLineEndVal)\r\n\r\n\r\n\r\n// alertcondition(buy__ut_bot_alerts, 'UT Long', 'UT Long')\r\n// alertcondition(sell__ut_bot_alerts, 'UT Short', 'UT Short')\r\n\r\n// new indicator: Super Trend by KIVANCOZBILGIC:\r\n\r\nPeriods_super_trend_ = input(title = 'ATR Period', defval = 9)\r\nsrc_super_trend_ = input(hl2, title = 'Source')\r\nMultiplier_super_trend_ = input.float(title = 'ATR Multiplier', step = 0.1, defval = 1.0)\r\nchangeATR_super_trend_ = input(title = 'Change ATR Calculation Method ?', defval = false)\r\nshowsignals_super_trend_ = input(title = 'Show Buy/Sell Signals ?', defval = false)\r\nhighlighting_super_trend_ = input(title = 'Highlighter On/Off ?', defval = true)\r\n\r\natr2_super_trend_ = ta.sma(ta.tr, Periods_super_trend_)\r\natr_super_trend_ = changeATR_super_trend_ ? ta.atr(Periods_super_trend_) : atr2_super_trend_\r\n\r\nup_super_trend_ = src_super_trend_ - Multiplier_super_trend_ * atr_super_trend_\r\nup1_super_trend_ = nz(up_super_trend_[1], up_super_trend_)\r\nup_super_trend_ := close[1] > up1_super_trend_ ? math.max(up_super_trend_, up1_super_trend_) : up_super_trend_\r\n\r\ndn_super_trend_ = src_super_trend_ + Multiplier_super_trend_ * atr_super_trend_\r\ndn1_super_trend_ = nz(dn_super_trend_[1], dn_super_trend_)\r\ndn_super_trend_ := close[1] < dn1_super_trend_ ? math.min(dn_super_trend_, dn1_super_trend_) : dn_super_trend_\r\n\r\ntrend_super_trend_ = 1\r\ntrend_super_trend_ := nz(trend_super_trend_[1], trend_super_trend_)\r\ntrend_super_trend_ := trend_super_trend_ == -1 and close > dn1_super_trend_ ? 1 : trend_super_trend_ == 1 and close < up1_super_trend_ ? -1 : trend_super_trend_\r\n\r\nupPlot_super_trend_ = plot(\r\n     trend_super_trend_ == 1 ? up_super_trend_ : na,\r\n     title = 'Up Trend',\r\n     style = plot.style_linebr,\r\n     linewidth = 6,\r\n     color = color.new(color.green, 0)\r\n)\r\n\r\nbuySignal_super_trend_ = trend_super_trend_ == 1 and trend_super_trend_[1] == -1\r\n\r\nplotshape(\r\n     buySignal_super_trend_ ? up_super_trend_ : na,\r\n     title = 'UpTrend Begins',\r\n     location = location.absolute,\r\n     style = shape.circle,\r\n     size = size.tiny,\r\n     color = color.new(color.green, 0)\r\n)\r\n\r\nplotshape(\r\n     buySignal_super_trend_ and showsignals_super_trend_ ? up_super_trend_ : na,\r\n     title = 'Buy',\r\n     text = 'Buy',\r\n     location = location.absolute,\r\n     style = shape.labelup,\r\n     size = size.tiny,\r\n     color = color.new(color.green, 0),\r\n     textcolor = color.new(color.white, 0)\r\n)\r\n\r\ndnPlot_super_trend_ = plot(\r\n     trend_super_trend_ == 1 ? na : dn_super_trend_,\r\n     title = 'Down Trend',\r\n     style = plot.style_linebr,\r\n     linewidth = 4,\r\n     color = color.new(color.red, 0)\r\n)\r\n\r\nsellSignal_super_trend_ = trend_super_trend_ == -1 and trend_super_trend_[1] == 1\r\n\r\nplotshape(\r\n     sellSignal_super_trend_ ? dn_super_trend_ : na,\r\n     title = 'DownTrend Begins',\r\n     location = location.absolute,\r\n     style = shape.circle,\r\n     size = size.tiny,\r\n     color = color.new(color.red, 0)\r\n)\r\n\r\nplotshape(\r\n     sellSignal_super_trend_ and showsignals_super_trend_ ? dn_super_trend_ : na,\r\n     title = 'Sell',\r\n     text = 'Sell',\r\n     location = location.absolute,\r\n     style = shape.labeldown,\r\n     size = size.tiny,\r\n     color = color.new(color.red, 0),\r\n     textcolor = color.new(color.white, 0)\r\n)\r\n\r\nmPlot_super_trend_ = plot(\r\n     ohlc4,\r\n     title = '',\r\n     style = plot.style_circles,\r\n     linewidth = math.max(1, 0)\r\n)\r\n\r\nlongFillColor_super_trend_ = highlighting_super_trend_ ? trend_super_trend_ == 1 ? #4caf4f6e : color.white : color.white\r\nshortFillColor_super_trend_ = highlighting_super_trend_ ? trend_super_trend_ == -1 ? #ff52522d : color.white : color.white\r\n\r\nfill(\r\n     mPlot_super_trend_,\r\n     upPlot_super_trend_,\r\n     title = 'UpTrend Highligter',\r\n     color = longFillColor_super_trend_\r\n)\r\n\r\nfill(\r\n     mPlot_super_trend_,\r\n     dnPlot_super_trend_,\r\n     title = 'DownTrend Highligter',\r\n     color = shortFillColor_super_trend_\r\n)\r\n\r\n// // new indicator: EMA 10/20/50/100/200\r\n\r\n\r\n\r\n// shortest__ = ta.ema(close, 10)\r\n// shorter__  = ta.ema(close, 20)\r\n// short__    = ta.ema(close, 50)\r\n// longer__   = ta.ema(close, 100)\r\n// longest__  = ta.ema(close, 200)\r\n\r\n// plot(shortest__, color= #66bb6a,    title=\"EMA 10\")\r\n// plot(shorter__,  color=#ff9800, title=\"EMA 20\")\r\n// plot(short__,    color=color.rgb(255, 255, 255, 100), title=\"EMA 50\")\r\n// plot(longer__,   color=color.rgb(255, 255, 255, 100),  title=\"EMA 100\")\r\n// plot(longest__,  color=#0404fd,   title=\"EMA 200\", linewidth = 6)\r\n\r\n\r\n// // new indicator: Kernel Regression Estimate\r\n\r\n// // Kernel Settings\r\n// h__kernal_regression_estimate   = input.int(8,    'Lookback Window',   minval=3)\r\n// r__kernal_regression_estimate   = input.float(8., 'Relative Weighting', step=0.25)\r\n// x__kernal_regression_estimate   = input.int(25,   'Regression Level')\r\n// lag__kernal_regression_estimate = input.int(2,    'Lag')\r\n\r\n// useKernelSmoothing__kernal_regression_estimate = input.bool(false, 'Enhance Kernel Smoothing')\r\n// showKernelEstimate__kernal_regression_estimate = input.bool(true,  'Show Kernel Estimate')\r\n\r\n// src__kernal_regression_estimate = input.source(close, 'Source')\r\n\r\n// // Kernel Calculations\r\n// yhat1__kernal_regression_estimate = kernels.rationalQuadratic(\r\n//     src__kernal_regression_estimate,\r\n//     h__kernal_regression_estimate,\r\n//     r__kernal_regression_estimate,\r\n//     x__kernal_regression_estimate\r\n// )\r\n\r\n// yhat2__kernal_regression_estimate = kernels.gaussian(\r\n//     src__kernal_regression_estimate,\r\n//     h__kernal_regression_estimate - lag__kernal_regression_estimate,\r\n//     x__kernal_regression_estimate\r\n// )\r\n\r\n// kernelEstimate__kernal_regression_estimate = yhat1__kernal_regression_estimate\r\n\r\n// // Rate of change for color\r\n// bool wasBullishRate__kernal_regression_estimate = yhat1__kernal_regression_estimate[2] < yhat1__kernal_regression_estimate[1]\r\n// bool isBullishRate__kernal_regression_estimate  = yhat1__kernal_regression_estimate[1] < yhat1__kernal_regression_estimate\r\n\r\n// bool isBullishSmooth__kernal_regression_estimate = yhat2__kernal_regression_estimate >= yhat1__kernal_regression_estimate\r\n\r\n// // Colors\r\n// c_green__kernal_regression_estimate = color.new(#3F4D42, 0)\r\n// c_red__kernal_regression_estimate   = color.new(#E91E63, 0)\r\n// transparent__kernal_regression_estimate = color.new(#000000, 100)\r\n\r\n// color colorByCross__kernal_regression_estimate = isBullishSmooth__kernal_regression_estimate ? c_green__kernal_regression_estimate : c_red__kernal_regression_estimate\r\n// color colorByRate__kernal_regression_estimate  = isBullishRate__kernal_regression_estimate ? c_green__kernal_regression_estimate : c_red__kernal_regression_estimate\r\n\r\n// color plotColor__kernal_regression_estimate =\r\n//      showKernelEstimate__kernal_regression_estimate ?\r\n//      (useKernelSmoothing__kernal_regression_estimate ?\r\n//      colorByCross__kernal_regression_estimate :\r\n//      colorByRate__kernal_regression_estimate) :\r\n//      transparent__kernal_regression_estimate\r\n\r\n// plot(\r\n//     kernelEstimate__kernal_regression_estimate,\r\n//     color=plotColor__kernal_regression_estimate,\r\n//     linewidth=6,\r\n//     title='Kernel Regression Estimate'\r\n// )\r\n\r\n// new indicator: Dynamic Swing Anchored VWAP: Zeiirman\r\n// ~~ Tooltips {\r\nvar string t1_Dynamic_Swing_Anchored_VWAP = \"Number of bars used to detect swing highs and lows. Larger values identify bigger, more significant swings but react slower. Smaller values detect more frequent swings but may produce more noise.\"\r\nvar string t2_Dynamic_Swing_Anchored_VWAP = \"Controls how quickly the VWAP adjusts to new price action. Lower values make the VWAP react faster (tighter to price), higher values make it smoother and slower to change.\"\r\nvar string t3_Dynamic_Swing_Anchored_VWAP = \"When enabled, the VWAP reaction speed changes automatically based on market volatility. High volatility shortens the tracking period (more responsive), low volatility lengthens it (smoother).\"\r\nvar string t4_Dynamic_Swing_Anchored_VWAP = \"Controls how strongly volatility influences the VWAP reaction speed. Values above 1 increase the effect of volatility changes; values below 1 make it less sensitive to volatility.\"\r\nvar string t5_Dynamic_Swing_Anchored_VWAP = \"Color used for swing high/low labels drawn on the chart to indicate pivot points.\"\r\nvar string t6_Dynamic_Swing_Anchored_VWAP = \"Color used for swing low labels when marking pivot points.\"\r\nvar string t7_Dynamic_Swing_Anchored_VWAP = \"Color used for the Upper / Bearish VWAP line (anchored from swing high).\"\r\nvar string t8_Dynamic_Swing_Anchored_VWAP = \"Color used for the Lower / Bullish VWAP line (anchored from swing low).\"\r\nvar string t9_Dynamic_Swing_Anchored_VWAP = \"Width of the VWAP lines drawn on the chart. Larger values make the lines thicker and more visible.\"\r\n//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}\r\n\r\n// ~~ Inputs {\r\nprd_Dynamic_Swing_Anchored_VWAP     = input.int(50, title='Swing Period', minval=2, group='Swing Points', tooltip=t1_Dynamic_Swing_Anchored_VWAP)\r\nbaseAPT_Dynamic_Swing_Anchored_VWAP = input.float(20, 'Adaptive Price Tracking', minval=1, step=1, group='Swing Points', tooltip=t2_Dynamic_Swing_Anchored_VWAP)\r\nuseAdapt_Dynamic_Swing_Anchored_VWAP= input.bool(false, 'Adapt APT by ATR ratio', group='Swing Points', tooltip=t3_Dynamic_Swing_Anchored_VWAP)\r\nvolBias_Dynamic_Swing_Anchored_VWAP = input.float(10.0, 'Volatility Bias', minval=0.1, step=0.1, group='Swing Points', tooltip=t4_Dynamic_Swing_Anchored_VWAP)\r\n\r\nhighS_Dynamic_Swing_Anchored_VWAP   = input.color(color.lime, title=\"Swing Labels\", group=\"Style\", inline=\"Swing\", tooltip=t5_Dynamic_Swing_Anchored_VWAP)\r\nlowS_Dynamic_Swing_Anchored_VWAP    = input.color(color.red,  title=\"\", group=\"Style\", inline=\"Swing\", tooltip=t6_Dynamic_Swing_Anchored_VWAP)\r\n\r\n// Upper (from Swing High) = #5500FE (Blue) | Lower (from Swing Low / LL) = #B210FD (Purple)\r\nupper_bearish_col                   = input.color(#FF8458, title=\"Upper (High) / Lower (Low)\", group=\"Style\", inline=\"VWAP\", tooltip=t7_Dynamic_Swing_Anchored_VWAP)\r\nlower_bullish_col                   = input.color(#01F1BF, title=\"\", group=\"Style\", inline=\"VWAP\", tooltip=t8_Dynamic_Swing_Anchored_VWAP)\r\nxx_Dynamic_Swing_Anchored_VWAP      = input.int(14, minval=1, title=\"Width\", group=\"Style\", inline=\"VWAP\", tooltip=t9_Dynamic_Swing_Anchored_VWAP)\r\n//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}\r\n\r\n// ~~ Global Variable {\r\nb_Dynamic_Swing_Anchored_VWAP = bar_index\r\n//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}\r\n\r\n// ~~ PIVOTS Variables {\r\nvar float ph_Dynamic_Swing_Anchored_VWAP   = na\r\nvar float pl_Dynamic_Swing_Anchored_VWAP   = na\r\nvar int   phL_Dynamic_Swing_Anchored_VWAP  = b_Dynamic_Swing_Anchored_VWAP\r\nvar int   plL_Dynamic_Swing_Anchored_VWAP  = b_Dynamic_Swing_Anchored_VWAP\r\nvar float prev_Dynamic_Swing_Anchored_VWAP = na\r\n\r\nph_Dynamic_Swing_Anchored_VWAP  := ta.highestbars(high, prd_Dynamic_Swing_Anchored_VWAP) == 0 ? high : ph_Dynamic_Swing_Anchored_VWAP\r\npl_Dynamic_Swing_Anchored_VWAP  := ta.lowestbars(low,  prd_Dynamic_Swing_Anchored_VWAP) == 0 ? low  : pl_Dynamic_Swing_Anchored_VWAP\r\nphL_Dynamic_Swing_Anchored_VWAP := ta.highestbars(high, prd_Dynamic_Swing_Anchored_VWAP) == 0 ? b_Dynamic_Swing_Anchored_VWAP : phL_Dynamic_Swing_Anchored_VWAP\r\nplL_Dynamic_Swing_Anchored_VWAP := ta.lowestbars(low,  prd_Dynamic_Swing_Anchored_VWAP) == 0 ? b_Dynamic_Swing_Anchored_VWAP : plL_Dynamic_Swing_Anchored_VWAP\r\ndir_Dynamic_Swing_Anchored_VWAP = phL_Dynamic_Swing_Anchored_VWAP > plL_Dynamic_Swing_Anchored_VWAP ? 1 : -1\r\n//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}\r\n\r\n// ~~ Adaptation {\r\natrLen_Dynamic_Swing_Anchored_VWAP = 50\r\natr_Dynamic_Swing_Anchored_VWAP    = ta.atr(atrLen_Dynamic_Swing_Anchored_VWAP)\r\natrAvg_Dynamic_Swing_Anchored_VWAP = ta.rma(atr_Dynamic_Swing_Anchored_VWAP, atrLen_Dynamic_Swing_Anchored_VWAP)\r\nratio_Dynamic_Swing_Anchored_VWAP  = atrAvg_Dynamic_Swing_Anchored_VWAP > 0 ? atr_Dynamic_Swing_Anchored_VWAP / atrAvg_Dynamic_Swing_Anchored_VWAP : 1.0\r\n\r\naptRaw_Dynamic_Swing_Anchored_VWAP     = useAdapt_Dynamic_Swing_Anchored_VWAP ? baseAPT_Dynamic_Swing_Anchored_VWAP / math.pow(ratio_Dynamic_Swing_Anchored_VWAP, volBias_Dynamic_Swing_Anchored_VWAP) : baseAPT_Dynamic_Swing_Anchored_VWAP\r\naptClamped_Dynamic_Swing_Anchored_VWAP = math.max(5.0, math.min(300.0, aptRaw_Dynamic_Swing_Anchored_VWAP))\r\naptSeries_Dynamic_Swing_Anchored_VWAP  = math.round(aptClamped_Dynamic_Swing_Anchored_VWAP)\r\n\r\nalphaFromAPT(float apt_Dynamic_Swing_Anchored_VWAP) =>\r\n    decay_Dynamic_Swing_Anchored_VWAP = math.exp(-math.log(2.0) / math.max(1.0, apt_Dynamic_Swing_Anchored_VWAP))\r\n    1.0 - decay_Dynamic_Swing_Anchored_VWAP\r\n//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}\r\n\r\n// ~~ VWAP Variables {\r\nvar float p_Dynamic_Swing_Anchored_VWAP   = hlc3 * volume \r\nvar float vol_Dynamic_Swing_Anchored_VWAP = volume      \r\n\r\ntype dataPoints\r\n    array<chart.point> points\r\n    polyline poly = na\r\n\r\nvar dataPoints vwap_Dynamic_Swing_Anchored_VWAP = dataPoints.new(array.new<chart.point>())\r\nvar float current_vwap = na\r\n\r\n// dir > 0 anchors to plL (Swing Low / LL / HL) -> Purple (#B210FD)\r\n// dir < 0 anchors to phL (Swing High / HH / LH) -> Blue (#5500FE)\r\nactive_vwap_color = dir_Dynamic_Swing_Anchored_VWAP > 0 ? lower_bullish_col : upper_bearish_col\r\n//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}\r\n\r\n// ~~ Main {\r\nif dir_Dynamic_Swing_Anchored_VWAP != dir_Dynamic_Swing_Anchored_VWAP[1]\r\n    x_Dynamic_Swing_Anchored_VWAP   = dir_Dynamic_Swing_Anchored_VWAP > 0 ? plL_Dynamic_Swing_Anchored_VWAP : phL_Dynamic_Swing_Anchored_VWAP\r\n    y_Dynamic_Swing_Anchored_VWAP   = dir_Dynamic_Swing_Anchored_VWAP > 0 ? pl_Dynamic_Swing_Anchored_VWAP  : ph_Dynamic_Swing_Anchored_VWAP\r\n    loc_Dynamic_Swing_Anchored_VWAP = dir_Dynamic_Swing_Anchored_VWAP > 0 ? label.style_label_up : label.style_label_down\r\n    col_Dynamic_Swing_Anchored_VWAP = dir_Dynamic_Swing_Anchored_VWAP > 0 ? highS_Dynamic_Swing_Anchored_VWAP : lowS_Dynamic_Swing_Anchored_VWAP\r\n    txt_Dynamic_Swing_Anchored_VWAP = dir_Dynamic_Swing_Anchored_VWAP > 0 and pl_Dynamic_Swing_Anchored_VWAP < prev_Dynamic_Swing_Anchored_VWAP ? 'LL' : dir_Dynamic_Swing_Anchored_VWAP > 0 and pl_Dynamic_Swing_Anchored_VWAP > prev_Dynamic_Swing_Anchored_VWAP ? 'HL' : dir_Dynamic_Swing_Anchored_VWAP < 0 and ph_Dynamic_Swing_Anchored_VWAP < prev_Dynamic_Swing_Anchored_VWAP ? 'LH' : dir_Dynamic_Swing_Anchored_VWAP < 0 and ph_Dynamic_Swing_Anchored_VWAP > prev_Dynamic_Swing_Anchored_VWAP ? 'HH' : ''\r\n    label.new(x_Dynamic_Swing_Anchored_VWAP, y_Dynamic_Swing_Anchored_VWAP, text=txt_Dynamic_Swing_Anchored_VWAP, style=loc_Dynamic_Swing_Anchored_VWAP, color=color.new(col_Dynamic_Swing_Anchored_VWAP, 20), textcolor=color.white)\r\n    prev_Dynamic_Swing_Anchored_VWAP := dir_Dynamic_Swing_Anchored_VWAP > 0 ? ph_Dynamic_Swing_Anchored_VWAP[1] : pl_Dynamic_Swing_Anchored_VWAP[1]\r\n\r\n    barsback_Dynamic_Swing_Anchored_VWAP = b_Dynamic_Swing_Anchored_VWAP - x_Dynamic_Swing_Anchored_VWAP\r\n    p_Dynamic_Swing_Anchored_VWAP   := y_Dynamic_Swing_Anchored_VWAP * volume[barsback_Dynamic_Swing_Anchored_VWAP]\r\n    vol_Dynamic_Swing_Anchored_VWAP := volume[barsback_Dynamic_Swing_Anchored_VWAP]\r\n    vap_Dynamic_Swing_Anchored_VWAP = p_Dynamic_Swing_Anchored_VWAP / vol_Dynamic_Swing_Anchored_VWAP\r\n\r\n    // Delete active line handle and preserve the previous completed segment using its previous direction color\r\n    vwap_Dynamic_Swing_Anchored_VWAP.poly.delete()\r\n    prev_vwap_color = dir_Dynamic_Swing_Anchored_VWAP[1] > 0 ? lower_bullish_col : upper_bearish_col\r\n    polyline.new(vwap_Dynamic_Swing_Anchored_VWAP.points, false, false, line_color = prev_vwap_color, line_width = xx_Dynamic_Swing_Anchored_VWAP)\r\n    vwap_Dynamic_Swing_Anchored_VWAP.points.clear()\r\n\r\n    for i_Dynamic_Swing_Anchored_VWAP = barsback_Dynamic_Swing_Anchored_VWAP to 0 by 1\r\n        apt_i_Dynamic_Swing_Anchored_VWAP = aptSeries_Dynamic_Swing_Anchored_VWAP[i_Dynamic_Swing_Anchored_VWAP]\r\n        alpha_Dynamic_Swing_Anchored_VWAP = alphaFromAPT(apt_i_Dynamic_Swing_Anchored_VWAP)\r\n\r\n        pxv_Dynamic_Swing_Anchored_VWAP   = hlc3[i_Dynamic_Swing_Anchored_VWAP] * volume[i_Dynamic_Swing_Anchored_VWAP]\r\n        v_i_Dynamic_Swing_Anchored_VWAP   = volume[i_Dynamic_Swing_Anchored_VWAP]\r\n\r\n        p_Dynamic_Swing_Anchored_VWAP     := (1.0 - alpha_Dynamic_Swing_Anchored_VWAP) * p_Dynamic_Swing_Anchored_VWAP + alpha_Dynamic_Swing_Anchored_VWAP * pxv_Dynamic_Swing_Anchored_VWAP\r\n        vol_Dynamic_Swing_Anchored_VWAP   := (1.0 - alpha_Dynamic_Swing_Anchored_VWAP) * vol_Dynamic_Swing_Anchored_VWAP + alpha_Dynamic_Swing_Anchored_VWAP * v_i_Dynamic_Swing_Anchored_VWAP\r\n        vappe_Dynamic_Swing_Anchored_VWAP = vol_Dynamic_Swing_Anchored_VWAP > 0 ? p_Dynamic_Swing_Anchored_VWAP / vol_Dynamic_Swing_Anchored_VWAP : na\r\n\r\n        vwap_Dynamic_Swing_Anchored_VWAP.points.push(chart.point.from_index(b_Dynamic_Swing_Anchored_VWAP - i_Dynamic_Swing_Anchored_VWAP, vappe_Dynamic_Swing_Anchored_VWAP))\r\n        if i_Dynamic_Swing_Anchored_VWAP == 0\r\n            current_vwap := vappe_Dynamic_Swing_Anchored_VWAP\r\n\r\n    vwap_Dynamic_Swing_Anchored_VWAP.poly := polyline.new(vwap_Dynamic_Swing_Anchored_VWAP.points, false, false, line_color = active_vwap_color, line_width = xx_Dynamic_Swing_Anchored_VWAP)\r\n\r\nelse\r\n    apt_0_Dynamic_Swing_Anchored_VWAP = aptSeries_Dynamic_Swing_Anchored_VWAP\r\n    alpha_Dynamic_Swing_Anchored_VWAP = alphaFromAPT(apt_0_Dynamic_Swing_Anchored_VWAP)\r\n\r\n    pxv_Dynamic_Swing_Anchored_VWAP = hlc3 * volume\r\n    v0_Dynamic_Swing_Anchored_VWAP  = volume\r\n\r\n    p_Dynamic_Swing_Anchored_VWAP   := (1.0 - alpha_Dynamic_Swing_Anchored_VWAP) * p_Dynamic_Swing_Anchored_VWAP + alpha_Dynamic_Swing_Anchored_VWAP * pxv_Dynamic_Swing_Anchored_VWAP\r\n    vol_Dynamic_Swing_Anchored_VWAP := (1.0 - alpha_Dynamic_Swing_Anchored_VWAP) * vol_Dynamic_Swing_Anchored_VWAP + alpha_Dynamic_Swing_Anchored_VWAP * v0_Dynamic_Swing_Anchored_VWAP\r\n    vap_Dynamic_Swing_Anchored_VWAP = vol_Dynamic_Swing_Anchored_VWAP > 0 ? p_Dynamic_Swing_Anchored_VWAP / vol_Dynamic_Swing_Anchored_VWAP : na\r\n\r\n    current_vwap := vap_Dynamic_Swing_Anchored_VWAP\r\n\r\n    vwap_Dynamic_Swing_Anchored_VWAP.poly.delete()\r\n    vwap_Dynamic_Swing_Anchored_VWAP.points.push(chart.point.from_index(b_Dynamic_Swing_Anchored_VWAP, vap_Dynamic_Swing_Anchored_VWAP))\r\n    vwap_Dynamic_Swing_Anchored_VWAP.poly := polyline.new(vwap_Dynamic_Swing_Anchored_VWAP.points, false, false, line_color = active_vwap_color, line_width = xx_Dynamic_Swing_Anchored_VWAP)\r\n//~~ }\r\n\r\n// ~~ Data Window Outputs {\r\nplot(current_vwap, title=\"Current VWAP Value\", color=color.new(color.white, 100), display=display.data_window)\r\nplot(dir_Dynamic_Swing_Anchored_VWAP, title=\"Swing Bias (+1 Buy / -1 Sell)\", color=color.new(color.white, 100), display=display.data_window)\r\n//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}\r\n// // new indicator: trend duration forecast [chartprime]\r\n// // --------------------------------------------------------------------------------------------------------------------}\r\n// // 📌 𝙐𝙎𝙀𝙍 𝙄𝙉𝙋𝙐𝙏𝙎\r\n// // --------------------------------------------------------------------------------------------------------------------{\r\n\r\n// length_trend_duration_forecast = input.int(\r\n//      50,\r\n//      title = \"Smoothing Length\",\r\n//      tooltip = \"Defines how many bars are used for the Hull Moving Average (HMA). A longer length smooths out short-term noise but increases lag.\"\r\n//  )\r\n// trendLength_trend_duration_forecast = input.int(\r\n//      3,\r\n//      title = \"Trend Detection Sensitivity\",\r\n//      tooltip = \"Controls how many consecutive bars are checked for rising/falling HMA slope. Lower values make trends switch faster, higher values make them more stable.\"\r\n//  )\r\n// samples_trend_duration_forecast = input.int(\r\n//      10,\r\n//      title = \"Trend Sample Size\",\r\n//      minval = 2,\r\n//      tooltip = \"Defines how many past trend durations are stored to calculate the average probable trend length. Larger samples produce smoother probability estimates.\"\r\n//  )\r\n// coloUP_trend_duration_forecast = input.color(color.rgb(18, 228, 158), \"↑ Trend\", inline = \"col\")\r\n// coloDN_trend_duration_forecast = input.color(color.rgb(236, 86, 16), \"↓ Trend\", inline = \"col\")\r\n\r\n\r\n// extend_mult = input.float(1.0, \"Extend Multiplier\", minval = 1.0, step = 0.5,\r\n//      tooltip = \"Multiplies the average trend duration to extend the forecast line further right.\")\r\n// extend_extra = input.int(0, \"Extend Extra Bars\", minval = 0,\r\n//      tooltip = \"Adds a fixed number of extra bars to the right extension of the forecast line.\")\r\n\r\n// var trend_trend_duration_forecast = bool(na)\r\n// var TrendCount_trend_duration_forecast = 0\r\n// var bullishCount_trend_duration_forecast = array.new<int>()\r\n// var bearishCount_trend_duration_forecast = array.new<int>()\r\n// var LengthLine_trend_duration_forecast = line(na)\r\n\r\n// // --------------------------------------------------------------------------------------------------------------------}\r\n// // 📌 𝙄𝙉𝘿𝙄𝘾𝘼𝙏𝙊𝙍 𝘾𝘼𝙇𝘾𝙐𝙇𝘼𝙏𝙄𝙊𝙉𝙎\r\n// // --------------------------------------------------------------------------------------------------------------------{\r\n\r\n// series float hma_trend_duration_forecast = ta.hma(close, length_trend_duration_forecast)\r\n\r\n// if barstate.isconfirmed\r\n//     if ta.rising(hma_trend_duration_forecast, trendLength_trend_duration_forecast)\r\n//         trend_trend_duration_forecast := true\r\n//     if ta.falling(hma_trend_duration_forecast, trendLength_trend_duration_forecast)\r\n//         trend_trend_duration_forecast := false\r\n\r\n// if trend_trend_duration_forecast or not trend_trend_duration_forecast\r\n//     TrendCount_trend_duration_forecast += 1\r\n\r\n// if trend_trend_duration_forecast != trend_trend_duration_forecast[1]\r\n//     LengthLine_trend_duration_forecast.delete()\r\n//     if trend_trend_duration_forecast\r\n//         bearishCount_trend_duration_forecast.push(TrendCount_trend_duration_forecast)\r\n//         LengthLine_trend_duration_forecast := line.new(\r\n//              bar_index - 1, hma_trend_duration_forecast[1], bar_index, hma_trend_duration_forecast[1],\r\n//              color = #b121f3, width = 4, style = line.style_arrow_right\r\n//          )\r\n//     else\r\n//         bullishCount_trend_duration_forecast.push(TrendCount_trend_duration_forecast)\r\n//         LengthLine_trend_duration_forecast := line.new(\r\n//              bar_index - 1, hma_trend_duration_forecast[1], bar_index, hma_trend_duration_forecast[1],\r\n//              color = chart.fg_color, style = line.style_arrow_right\r\n//          )\r\n//     TrendCount_trend_duration_forecast := 0\r\n\r\n// // DYNAMIC LINE UPDATES\r\n// if not trend_trend_duration_forecast\r\n//     LengthLine_trend_duration_forecast.set_x2(LengthLine_trend_duration_forecast.get_x1() + int(bearishCount_trend_duration_forecast.avg() * extend_mult) + extend_extra)\r\n//     LengthLine_trend_duration_forecast.set_color(#ff525200)\r\n//     LengthLine_trend_duration_forecast.set_width(14)\r\n// else\r\n//     LengthLine_trend_duration_forecast.set_x2(LengthLine_trend_duration_forecast.get_x1() + int(bullishCount_trend_duration_forecast.avg() * extend_mult) + extend_extra)\r\n\r\n// if bullishCount_trend_duration_forecast.size() > samples_trend_duration_forecast\r\n//     bullishCount_trend_duration_forecast.shift()\r\n// if bearishCount_trend_duration_forecast.size() > samples_trend_duration_forecast\r\n//     bearishCount_trend_duration_forecast.shift()\r\n\r\n// // --------------------------------------------------------------------------------------------------------------------}\r\n// // 📌 𝙑𝙄𝙎𝙐𝘼𝙇𝙄𝙕𝘼𝙏𝙄𝙊𝙉\r\n// // --------------------------------------------------------------------------------------------------------------------{\r\n\r\n// TColor_trend_duration_forecast = trend_trend_duration_forecast ? coloUP_trend_duration_forecast : coloDN_trend_duration_forecast\r\n// plot(hma_trend_duration_forecast, \"HMA\", TColor_trend_duration_forecast, linewidth = 2)\r\n\r\n// new indicator: ema\r\n// ———————— Inputs ————————\r\n// EMA Lengths\r\nema20_len   = input.int(20, 'EMA 20 Length', group='Moving Average', minval=1)\r\nema200_len  = input.int(200, 'EMA 200 Length', group='Moving Average', minval=1)\r\n\r\n// Display Options - EMA 20\r\nshow_ema20_curve = input.bool(true, 'Show 20 EMA Curve Line', group='EMA 20 Display Options')\r\nshow_ema20_dots  = input.bool(true, 'Show 20 EMA Dotted Line', group='EMA 20 Display Options')\r\n\r\n// Display Options - EMA 200\r\nshow_ema200_curve = input.bool(true, 'Show 200 EMA Curve Line', group='EMA 200 Display Options')\r\nshow_ema200_dots  = input.bool(true, 'Show 200 EMA Dotted Line', group='EMA 200 Display Options')\r\n\r\n// Style Settings - EMA 20\r\nema20_color   = input.color(color.orange, 'EMA 20 Color', group='EMA 20 Style')\r\ndot_width_20  = input.int(6, 'EMA 20 Dotted Line Width', minval=1, maxval=20, group='EMA 20 Style')\r\n\r\n// Style Settings - EMA 200\r\nema200_color  = input.color(#B210FD, 'EMA 200 Color', group='EMA 200 Style')\r\ndot_width_200 = input.int(6, 'EMA 200 Dotted Line Width', minval=1, maxval=20, group='EMA 200 Style')\r\n\r\n// ———————— Calculations ————————\r\nema20  = ta.ema(close, ema20_len)\r\nema200 = ta.ema(close, ema200_len)\r\n\r\n// ———————— Curve Plots ————————\r\nplot(show_ema20_curve ? ema20 : na, 'EMA 20 Curve', color=ema20_color, linewidth=10)\r\nplot(show_ema200_curve ? ema200 : na, 'EMA 200 Curve', color=ema200_color, linewidth=6)\r\n\r\n// ———————— Dotted Horizontal Track Lines ————————\r\nvar line line_ema20  = na\r\nvar line line_ema200 = na\r\n\r\nif barstate.islast\r\n    // Update EMA 20 dotted horizontal track line\r\n    line.delete(line_ema20)\r\n    if show_ema20_dots\r\n        line_ema20 := line.new(bar_index - 1, ema20, bar_index, ema20, extend=extend.both, style=line.style_dotted, color=ema20_color, width=dot_width_20)\r\n\r\n    // Update EMA 200 dotted horizontal track line\r\n    line.delete(line_ema200)\r\n    if show_ema200_dots\r\n        line_ema200 := line.new(bar_index - 1, ema200, bar_index, ema200, extend=extend.both, style=line.style_dotted, color=ema200_color, width=dot_width_200)\r\n// new indicator: order Blocks Finder [TradingFinder] Major OB + Supply and Demand Zones\r\n// (Demand = blue, Supply = red, both drawn the same way)\r\n// ─── INPUTS ───────────────────────────────────────────────────────────────────\r\nOBRefine__ = input.string('On', 'Order Block Refine', ['On', 'Off'], group = 'Order Block Setting')\r\nRefineType__ = input.string('Defensive', 'Refine Type', ['Defensive', 'Aggressive'], group = 'Order Block Setting')\r\nOBLineWidth__ = input.int(5, 'Order Block Line Width', minval = 1, maxval = 10, group = 'Order Block Setting')\r\n\r\n\r\n// ─── CANDLE BASICS ────────────────────────────────────────────────────────────\r\nCandle_Range__ = high - low\r\nCandle_Body__ = close - open\r\n\r\n\r\n// ─── CANDLE BREAK DETECTOR ───────────────────────────────────────────────────\r\nvar string Candle_Break__ = ''\r\nif close > high[1]\r\n    Candle_Break__ := 'Candle Bull Break'\r\nelse if close < low[1]\r\n    Candle_Break__ := 'Candle Bear Break'\r\n\r\n\r\n// ─── BAR INDICES FOR BULL / BEAR BREAKS ──────────────────────────────────────\r\nbar_index_bull__ = ta.valuewhen(close > high[1], bar_index, 0)\r\nbar_index_bear__ = ta.valuewhen(close < low[1], bar_index, 0)\r\n\r\n\r\nvar int start_bar_index_high__ = 0\r\nvar int start_bar_index_low__ = 0\r\n\r\n\r\n// ─── DYNAMIC LOOKBACK LENGTHS ────────────────────────────────────────────────\r\nlenHighest__ = bar_index - bar_index_bear__ + 5\r\nlenLowest__ = bar_index - bar_index_bull__ + 5\r\n\r\n\r\nlenHighest1__ = bar_index - bar_index_bear__ + 3\r\nlenLowest1__ = bar_index - bar_index_bull__ + 3\r\n\r\n\r\nHighestLen__ = na(lenHighest__) ? 1 : lenHighest__\r\nLowestLen__ = na(lenLowest__) ? 1 : lenLowest__\r\nHighestLen1__ = na(lenHighest1__) ? 1 : lenHighest1__\r\nLowestLen1__ = na(lenLowest1__) ? 1 : lenLowest1__\r\n\r\n\r\n// ─── HIGH / LOW DETECTORS ────────────────────────────────────────────────────\r\nHigh_first__ = ta.highest(high, HighestLen__)\r\nLow_first__ = ta.lowest(low, LowestLen__)\r\nHigh_first1__ = ta.highest(high, HighestLen1__)\r\nLow_first1__ = ta.lowest(low, LowestLen1__)\r\n\r\n\r\n// ─── CORRECTED HIGH / LOW ────────────────────────────────────────────────────\r\nvar float High_Correct__ = 0.0\r\nvar float Low_Correct__ = 0.0\r\n\r\nis_high_pivot = Candle_Break__ == 'Candle Bear Break' and Candle_Break__[1] == 'Candle Bull Break'\r\nif is_high_pivot\r\n    start_bar_index_high__ := bar_index\r\n\r\nHigh_sec__ = is_high_pivot ? (High_Correct__[1] == High_first__ ? High_first1__ : High_first__) : na\r\n\r\nis_low_pivot = Candle_Break__ == 'Candle Bull Break' and Candle_Break__[1] == 'Candle Bear Break'\r\nif is_low_pivot\r\n    start_bar_index_low__ := bar_index\r\n\r\nLow_sec__ = is_low_pivot ? (Low_Correct__[1] == Low_first__ ? Low_first1__ : Low_first__) : na\r\n\r\nif not na(High_sec__)\r\n    High_Correct__ := High_sec__\r\n\r\nif not na(Low_sec__)\r\n    Low_Correct__ := Low_sec__\r\n\r\n\r\n// ─── MAJOR HIGH / LOW (filtered) ─────────────────────────────────────────────\r\nvar int bar_index_bull_BoS__ = 0\r\nvar int bar_index_bear_BoS__ = 0\r\nvar string BoS__ = 'Hi'\r\nvar float High_Correct_f__ = 0.0\r\nvar float Low_Correct_f__ = 0.0\r\n\r\n\r\nif (na(High_Correct_f__) or High_Correct_f__ == 0) and not na(High_Correct__) and High_Correct__ != 0\r\n    High_Correct_f__ := High_Correct__\r\nelse if not na(High_Correct__) and High_Correct__ > nz(High_Correct_f__[1]) and High_Correct__ != 0\r\n    High_Correct_f__ := High_Correct__\r\nelse if not na(High_Correct__) and High_Correct__ < nz(High_Correct_f__[1]) and BoS__ == 'Bear BoS' and bar_index_bear_BoS__ >= start_bar_index_high__\r\n    High_Correct_f__ := High_Correct__\r\nelse\r\n    High_Correct_f__ := High_Correct_f__[1]\r\n\r\n\r\nif (na(Low_Correct_f__) or Low_Correct_f__ == 0) and not na(Low_Correct__) and Low_Correct__ != 0\r\n    Low_Correct_f__ := Low_Correct__\r\nelse if not na(Low_Correct__) and Low_Correct__ < nz(Low_Correct_f__[1], 1e9) and Low_Correct__ != 0\r\n    Low_Correct_f__ := Low_Correct__\r\nelse if not na(Low_Correct__) and Low_Correct__ > nz(Low_Correct_f__[1]) and BoS__ == 'Bull BoS' and bar_index_bull_BoS__ >= start_bar_index_low__\r\n    Low_Correct_f__ := Low_Correct__\r\nelse\r\n    Low_Correct_f__ := Low_Correct_f__[1]\r\n\r\n\r\n// ─── BREAK OF STRUCTURE ───────────────────────────────────────────────────────\r\nif nz(High_Correct_f__) > 0 and close > High_Correct_f__ and close[1] <= High_Correct_f__\r\n    BoS__ := 'Bull BoS'\r\n    bar_index_bull_BoS__ := bar_index\r\nelse if nz(Low_Correct_f__) > 0 and close < Low_Correct_f__ and close[1] >= Low_Correct_f__\r\n    BoS__ := 'Bear BoS'\r\n    bar_index_bear_BoS__ := bar_index\r\nelse\r\n    BoS__ := '0'\r\n\r\n\r\n// ─── ORDER BLOCK BAR INDEX + CONDITIONS ──────────────────────────────────────\r\nbar_index_Demand_OB__ = ta.valuewhen(Low_Correct__ != Low_Correct__[1], bar_index[1], 0)\r\nbar_index_Supply_OB__ = ta.valuewhen(High_Correct__ != High_Correct__[1], bar_index[1], 0)\r\n\r\n\r\nvar int DemandCheck__ = 0\r\nvar int SupplyCheck__ = 0\r\n\r\n\r\nDemand_OB_Condition__ = (BoS__ == 'Bull BoS' and bar_index_bull_BoS__[1] > bar_index_bear_BoS__ or BoS__ == 'Bull BoS' and bar_index_bull_BoS__ > bar_index_bear_BoS__) and DemandCheck__ != bar_index_Demand_OB__\r\nSupply_OB_Condition__ = (BoS__ == 'Bear BoS' and bar_index_bear_BoS__[1] > bar_index_bull_BoS__ or BoS__ == 'Bear BoS' and bar_index_bear_BoS__ > bar_index_bull_BoS__) and SupplyCheck__ != bar_index_Supply_OB__\r\n\r\n\r\n// ─── ATR ──────────────────────────────────────────────────────────────────────\r\nATR__ = ta.atr(55)\r\n\r\n\r\n// ═════════════════════════════════════════════════════════════════════════════\r\n// DEMAND SIDE\r\n// ═════════════════════════════════════════════════════════════════════════════\r\n\r\n// ─── DEMAND CANDLE RANGES (around OB candle) ─────────────────────────────────\r\nvar float DCRa1__ = 0.0\r\nvar float DCRO__ = 0.0\r\n\r\n\r\nif bar_index >= bar_index_Demand_OB__ + 1\r\n    DCRa1__ := Candle_Range__[bar_index - bar_index_Demand_OB__ + 1]\r\n    DCRO__ := Candle_Range__[bar_index - bar_index_Demand_OB__]\r\n    DCRO__\r\n\r\n\r\n// ─── DEMAND MIN / MAX OHLC (window around OB) ────────────────────────────────\r\nvar float DminOpen__ = 0.0\r\nvar float DminHigh__ = 0.0\r\nvar float DminLow__ = 0.0\r\nvar float DminClose__ = 0.0\r\nvar float DmaxOpen__ = 0.0\r\nvar float DmaxHigh__ = 0.0\r\nvar float DmaxLow__ = 0.0\r\nvar float DmaxClose__ = 0.0\r\n\r\n\r\nif bar_index > bar_index_Demand_OB__ + 1\r\n    DminOpen__ := math.min(open[bar_index - bar_index_Demand_OB__ - 2], open[bar_index - bar_index_Demand_OB__ + 1], open[bar_index - bar_index_Demand_OB__], open[bar_index - bar_index_Demand_OB__ - 1])\r\n    DminHigh__ := math.min(high[bar_index - bar_index_Demand_OB__ - 2], high[bar_index - bar_index_Demand_OB__ + 1], high[bar_index - bar_index_Demand_OB__], high[bar_index - bar_index_Demand_OB__ - 1])\r\n    DminLow__ := math.min(low[bar_index - bar_index_Demand_OB__ - 2], low[bar_index - bar_index_Demand_OB__ + 1], low[bar_index - bar_index_Demand_OB__], low[bar_index - bar_index_Demand_OB__ - 1])\r\n    DminClose__ := math.min(close[bar_index - bar_index_Demand_OB__ - 2], close[bar_index - bar_index_Demand_OB__ + 1], close[bar_index - bar_index_Demand_OB__], close[bar_index - bar_index_Demand_OB__ - 1])\r\n    DmaxOpen__ := math.max(open[bar_index - bar_index_Demand_OB__ - 2], open[bar_index - bar_index_Demand_OB__ + 1], open[bar_index - bar_index_Demand_OB__], open[bar_index - bar_index_Demand_OB__ - 1])\r\n    DmaxHigh__ := math.max(high[bar_index - bar_index_Demand_OB__ - 2], high[bar_index - bar_index_Demand_OB__ + 1], high[bar_index - bar_index_Demand_OB__], high[bar_index - bar_index_Demand_OB__ - 1])\r\n    DmaxLow__ := math.max(low[bar_index - bar_index_Demand_OB__ - 2], low[bar_index - bar_index_Demand_OB__ + 1], low[bar_index - bar_index_Demand_OB__], low[bar_index - bar_index_Demand_OB__ - 1])\r\n    DmaxClose__ := math.max(close[bar_index - bar_index_Demand_OB__ - 2], close[bar_index - bar_index_Demand_OB__ + 1], close[bar_index - bar_index_Demand_OB__], close[bar_index - bar_index_Demand_OB__ - 1])\r\n    DmaxClose__\r\nelse if bar_index >= bar_index_Demand_OB__\r\n    DminOpen__ := math.min(open[bar_index - bar_index_Demand_OB__ + 1], open[bar_index - bar_index_Demand_OB__], open[bar_index - bar_index_Demand_OB__ - 1])\r\n    DminHigh__ := math.min(high[bar_index - bar_index_Demand_OB__ + 1], high[bar_index - bar_index_Demand_OB__], high[bar_index - bar_index_Demand_OB__ - 1])\r\n    DminLow__ := math.min(low[bar_index - bar_index_Demand_OB__ + 1], low[bar_index - bar_index_Demand_OB__], low[bar_index - bar_index_Demand_OB__ - 1])\r\n    DminClose__ := math.min(close[bar_index - bar_index_Demand_OB__ + 1], close[bar_index - bar_index_Demand_OB__], close[bar_index - bar_index_Demand_OB__ - 1])\r\n    DmaxOpen__ := math.max(open[bar_index - bar_index_Demand_OB__ + 1], open[bar_index - bar_index_Demand_OB__], open[bar_index - bar_index_Demand_OB__ - 1])\r\n    DmaxHigh__ := math.max(high[bar_index - bar_index_Demand_OB__ + 1], high[bar_index - bar_index_Demand_OB__], high[bar_index - bar_index_Demand_OB__ - 1])\r\n    DmaxLow__ := math.max(low[bar_index - bar_index_Demand_OB__ + 1], low[bar_index - bar_index_Demand_OB__], low[bar_index - bar_index_Demand_OB__ - 1])\r\n    DmaxClose__ := math.max(close[bar_index - bar_index_Demand_OB__ + 1], close[bar_index - bar_index_Demand_OB__], close[bar_index - bar_index_Demand_OB__ - 1])\r\n    DmaxClose__\r\n\r\n\r\n// ─── DEMAND OB REFINER (Aggressive levels) ───────────────────────────────────\r\nvar float DDA__ = 0.0 // Demand Distal  Aggressive\r\nvar float DPA__ = 0.0 // Demand Proximal Aggressive\r\n\r\n\r\nif DCRO__ <= ATR__ * 0.5\r\n    DPA__ := high[bar_index - bar_index_Demand_OB__]\r\n    DDA__ := DminLow__\r\n    DDA__\r\nelse if DCRO__ > ATR__ * 0.5 and DCRO__ <= ATR__\r\n    DPA__ := Candle_Body__ >= 0 ? close[bar_index - bar_index_Demand_OB__] : open[bar_index - bar_index_Demand_OB__]\r\n    DDA__ := DminLow__\r\n    DDA__\r\nelse if DCRO__ > ATR__\r\n    if low[bar_index - bar_index_Demand_OB__ + 1] < high[bar_index - bar_index_Demand_OB__]\r\n        if low[bar_index - bar_index_Demand_OB__ + 1] > low[bar_index - bar_index_Demand_OB__]\r\n            DPA__ := low[bar_index - bar_index_Demand_OB__ + 1]\r\n            DDA__ := low[bar_index - bar_index_Demand_OB__]\r\n            DDA__\r\n        else\r\n            if Candle_Body__[bar_index - bar_index_Demand_OB__ + 1] >= 0\r\n                DPA__ := DCRa1__ > ATR__ ? DmaxOpen__ : DmaxClose__\r\n                DDA__ := DminLow__\r\n                DDA__\r\n            else\r\n                DPA__ := DmaxOpen__\r\n                DDA__ := DminLow__\r\n                DDA__\r\n    else\r\n        if DminLow__ - DminOpen__ > DminLow__ - DminClose__ and DminLow__ - DminOpen__ <= ATR__ and DminLow__ - DminOpen__ >= ATR__ * 0.5\r\n            DPA__ := DminOpen__\r\n            DDA__ := DminLow__\r\n            DDA__\r\n        else if DminLow__ - DminOpen__ < DminLow__ - DminClose__ and DminLow__ - DminClose__ <= ATR__ and DminLow__ - DminClose__ >= ATR__ * 0.5\r\n            DPA__ := DminClose__\r\n            DDA__ := DminLow__\r\n            DDA__\r\nelse\r\n    DPA__ := Candle_Body__ > 0 ? DmaxHigh__ : DmaxHigh__\r\n    DDA__ := Candle_Body__ > 0 ? DminLow__ : DmaxLow__\r\n    DDA__\r\n\r\n\r\n// ─── DEMAND DEFENSIVE SHRINK ─────────────────────────────────────────────────\r\nvar float DProximal__ = 0.0\r\nvar float DDistal__ = 0.0\r\nif RefineType__ == 'Defensive'\r\n    float ratio__ = DPA__ - DDA__ >= ATR__ * 3 ? 0.7 : DPA__ - DDA__ >= ATR__ * 2 ? 0.6 : DPA__ - DDA__ >= ATR__ * 1.6 ? 0.5 : DPA__ - DDA__ > ATR__ ? 0.25 : 0.0\r\n    DDistal__ := DDA__\r\n    DProximal__ := ratio__ == 0.0 ? DPA__ : DPA__ - (DPA__ - DDA__) * ratio__\r\n    DProximal__\r\nelse\r\n    DDistal__ := DDA__\r\n    DProximal__ := DPA__\r\n    DProximal__\r\n\r\n\r\n// ─── DEMAND ZONE COORDINATES ─────────────────────────────────────────────────\r\nvar float YDp12__ = 0.0 // proximal price\r\nvar float YDd12__ = 0.0 // distal  price\r\nvar int XDp1__ = 0\r\nvar int XDd1__ = 0\r\nvar int XDp2__ = 0\r\n\r\n\r\nif Demand_OB_Condition__\r\n    DemandCheck__ := bar_index_Demand_OB__\r\n    YDp12__ := OBRefine__ == 'On' ? DProximal__ : high[bar_index - bar_index_Demand_OB__]\r\n    YDd12__ := OBRefine__ == 'On' ? DDistal__ : low[bar_index - bar_index_Demand_OB__]\r\n    XDp1__ := bar_index_Demand_OB__\r\n    XDd1__ := bar_index_Demand_OB__\r\n    XDp2__ := bar_index_Demand_OB__ + 1\r\n    XDp2__\r\n\r\n\r\n// ─── DEMAND OB DRAWING (blue) ────────────────────────────────────────────────\r\nvar bool DemCheck__ = true\r\nvar int DemCounter__ = 1\r\nvar line Distal__ = na\r\nvar line Proximal__ = na\r\nvar line DLine50per__ = na\r\nvar box demBox__ = na\r\n\r\n\r\nif Demand_OB_Condition__\r\n    Distal__ := line.new(XDd1__, YDd12__, XDp2__, YDd12__, color = #2962FF, style = line.style_solid, width = OBLineWidth__)\r\n    Proximal__ := line.new(XDp1__, YDp12__, XDp2__, YDp12__, color = #2962FF, style = line.style_solid, width = OBLineWidth__)\r\n    DLine50per__ := line.new(XDp1__, (YDp12__ + YDd12__) / 2, XDp2__, (YDp12__ + YDd12__) / 2, color = #2962FF, style = line.style_dotted, width = OBLineWidth__)\r\n    demBox__ := box.new(XDp1__, math.max(YDp12__, YDd12__), XDp2__, math.min(YDp12__, YDd12__), bgcolor = color.new(#2962FF, 85), border_color = color.new(#2962FF, 100), border_width = 0, text = '', text_size = size.small, text_color = color.white, text_halign = text.align_right)\r\n    DemCounter__ := 1\r\n    DemCheck__ := true\r\n    DemCheck__\r\n\r\n\r\nif (low > YDd12__ or XDd1__ == YDp12__[1]) and DemCheck__ == true and not na(Distal__)\r\n    DemCounter__ := DemCounter__ + 1\r\n    line.set_x2(Distal__, bar_index + 1)\r\n    line.set_x2(Proximal__, bar_index + 1)\r\n    line.set_x2(DLine50per__, bar_index + 1)\r\n    if not na(demBox__)\r\n        box.set_right(demBox__, bar_index + 1)\r\n\r\n\r\nif low < YDd12__ and low[1] > YDd12__\r\n    DemCheck__ := false\r\n    DemCheck__\r\n\r\n\r\n// ═════════════════════════════════════════════════════════════════════════════\r\n// SUPPLY SIDE (refiner logic taken from the original TradingFinder script)\r\n// ═════════════════════════════════════════════════════════════════════════════\r\n\r\n// ─── SUPPLY CANDLE RANGES (around OB candle) ─────────────────────────────────\r\nvar float SCRa1__ = 0.0\r\nvar float SCRO__ = 0.0\r\n\r\n\r\n// (same as the original indicator: computed on every bar)\r\nSCRa1__ := high[bar_index - bar_index_Supply_OB__ + 1] - low[bar_index - bar_index_Supply_OB__ + 1]\r\nSCRO__ := high[bar_index - bar_index_Supply_OB__] - low[bar_index - bar_index_Supply_OB__]\r\n\r\n\r\n// ─── SUPPLY MIN / MAX OHLC (window around OB) ────────────────────────────────\r\nvar float SminOpen__ = 0.0\r\nvar float SminHigh__ = 0.0\r\nvar float SminLow__ = 0.0\r\nvar float SminClose__ = 0.0\r\nvar float SmaxOpen__ = 0.0\r\nvar float SmaxHigh__ = 0.0\r\nvar float SmaxLow__ = 0.0\r\nvar float SmaxClose__ = 0.0\r\n\r\n\r\nif bar_index > bar_index_Supply_OB__ + 1\r\n    SminOpen__ := math.min(open[bar_index - bar_index_Supply_OB__ - 2], open[bar_index - bar_index_Supply_OB__ + 1], open[bar_index - bar_index_Supply_OB__], open[bar_index - bar_index_Supply_OB__ - 1])\r\n    SminHigh__ := math.min(high[bar_index - bar_index_Supply_OB__ - 2], high[bar_index - bar_index_Supply_OB__ + 1], high[bar_index - bar_index_Supply_OB__], high[bar_index - bar_index_Supply_OB__ - 1])\r\n    SminLow__ := math.min(low[bar_index - bar_index_Supply_OB__ - 2], low[bar_index - bar_index_Supply_OB__ + 1], low[bar_index - bar_index_Supply_OB__], low[bar_index - bar_index_Supply_OB__ - 1])\r\n    SminClose__ := math.min(close[bar_index - bar_index_Supply_OB__ - 2], close[bar_index - bar_index_Supply_OB__ + 1], close[bar_index - bar_index_Supply_OB__], close[bar_index - bar_index_Supply_OB__ - 1])\r\n    SmaxOpen__ := math.max(open[bar_index - bar_index_Supply_OB__ - 2], open[bar_index - bar_index_Supply_OB__ + 1], open[bar_index - bar_index_Supply_OB__], open[bar_index - bar_index_Supply_OB__ - 1])\r\n    SmaxHigh__ := math.max(high[bar_index - bar_index_Supply_OB__ - 2], high[bar_index - bar_index_Supply_OB__ + 1], high[bar_index - bar_index_Supply_OB__], high[bar_index - bar_index_Supply_OB__ - 1])\r\n    SmaxLow__ := math.max(low[bar_index - bar_index_Supply_OB__ - 2], low[bar_index - bar_index_Supply_OB__ + 1], low[bar_index - bar_index_Supply_OB__], low[bar_index - bar_index_Supply_OB__ - 1])\r\n    SmaxClose__ := math.max(close[bar_index - bar_index_Supply_OB__ - 2], close[bar_index - bar_index_Supply_OB__ + 1], close[bar_index - bar_index_Supply_OB__], close[bar_index - bar_index_Supply_OB__ - 1])\r\n    SmaxClose__\r\nelse if bar_index >= bar_index_Supply_OB__\r\n    SminOpen__ := math.min(open[bar_index - bar_index_Supply_OB__ + 1], open[bar_index - bar_index_Supply_OB__], open[bar_index - bar_index_Supply_OB__ - 1])\r\n    SminHigh__ := math.min(high[bar_index - bar_index_Supply_OB__ + 1], high[bar_index - bar_index_Supply_OB__], high[bar_index - bar_index_Supply_OB__ - 1])\r\n    SminLow__ := math.min(low[bar_index - bar_index_Supply_OB__ + 1], low[bar_index - bar_index_Supply_OB__], low[bar_index - bar_index_Supply_OB__ - 1])\r\n    SminClose__ := math.min(close[bar_index - bar_index_Supply_OB__ + 1], close[bar_index - bar_index_Supply_OB__], close[bar_index - bar_index_Supply_OB__ - 1])\r\n    SmaxOpen__ := math.max(open[bar_index - bar_index_Supply_OB__ + 1], open[bar_index - bar_index_Supply_OB__], open[bar_index - bar_index_Supply_OB__ - 1])\r\n    SmaxHigh__ := math.max(high[bar_index - bar_index_Supply_OB__ + 1], high[bar_index - bar_index_Supply_OB__], high[bar_index - bar_index_Supply_OB__ - 1])\r\n    SmaxLow__ := math.max(low[bar_index - bar_index_Supply_OB__ + 1], low[bar_index - bar_index_Supply_OB__], low[bar_index - bar_index_Supply_OB__ - 1])\r\n    SmaxClose__ := math.max(close[bar_index - bar_index_Supply_OB__ + 1], close[bar_index - bar_index_Supply_OB__], close[bar_index - bar_index_Supply_OB__ - 1])\r\n    SmaxClose__\r\n\r\n\r\n// ─── SUPPLY OB REFINER (Aggressive levels) ───────────────────────────────────\r\n// Supply distal = TOP of the zone, supply proximal = BOTTOM of the zone\r\nvar float SDA__ = 0.0 // Supply Distal  Aggressive\r\nvar float SPA__ = 0.0 // Supply Proximal Aggressive\r\n\r\n\r\nif SCRO__ <= ATR__ * 0.5\r\n    SPA__ := low[bar_index - bar_index_Supply_OB__]\r\n    SDA__ := SmaxHigh__\r\n    SDA__\r\nelse if SCRO__ > ATR__ * 0.5 and SCRO__ <= ATR__\r\n    SPA__ := Candle_Body__ >= 0 ? close[bar_index - bar_index_Supply_OB__] : open[bar_index - bar_index_Supply_OB__]\r\n    SDA__ := SmaxHigh__\r\n    SDA__\r\nelse if SCRO__ > ATR__\r\n    if high[bar_index - bar_index_Supply_OB__ + 1] > low[bar_index - bar_index_Supply_OB__]\r\n        if high[bar_index - bar_index_Supply_OB__ + 1] > high[bar_index - bar_index_Supply_OB__]\r\n            SPA__ := high[bar_index - bar_index_Supply_OB__ + 1]\r\n            SDA__ := high[bar_index - bar_index_Supply_OB__]\r\n            SDA__\r\n        else if high[bar_index - bar_index_Supply_OB__ + 1] <= high[bar_index - bar_index_Supply_OB__]\r\n            if Candle_Body__[bar_index - bar_index_Supply_OB__ + 1] > 0 or Candle_Body__[bar_index - bar_index_Supply_OB__ + 1] == 0\r\n                if SCRa1__ > ATR__\r\n                    SPA__ := SminClose__\r\n                    SDA__ := SmaxHigh__\r\n                    SDA__\r\n                else if SCRa1__ < ATR__\r\n                    SPA__ := SminOpen__\r\n                    SDA__ := SmaxHigh__\r\n                    SDA__\r\n            else if Candle_Body__[bar_index - bar_index_Supply_OB__ + 1] < 0\r\n                if SCRa1__ > ATR__\r\n                    SPA__ := SminOpen__\r\n                    SDA__ := SmaxHigh__\r\n                    SDA__\r\n                else if SCRa1__ < ATR__\r\n                    SPA__ := SmaxHigh__\r\n                    SDA__ := high[bar_index - bar_index_Supply_OB__ + 1]\r\n                    SDA__\r\n    else if not(high[bar_index - bar_index_Supply_OB__ + 1] > low[bar_index - bar_index_Supply_OB__])\r\n        if SmaxHigh__ - SminOpen__ > SmaxHigh__ - SminClose__ and SmaxHigh__ - SminOpen__ <= ATR__ and SmaxHigh__ - SminOpen__ >= ATR__ * 0.5\r\n            SPA__ := SminOpen__\r\n            SDA__ := SmaxHigh__\r\n            SDA__\r\n        else if SmaxHigh__ - SminOpen__ < SmaxHigh__ - SminClose__ and SmaxHigh__ - SminClose__ <= ATR__ and SmaxHigh__ - SminClose__ >= ATR__ * 0.5\r\n            SPA__ := SminClose__\r\n            SDA__ := SmaxHigh__\r\n            SDA__\r\nelse\r\n    SPA__ := SminLow__\r\n    SDA__ := SmaxHigh__\r\n    SDA__\r\n\r\n\r\n// ─── SUPPLY DEFENSIVE SHRINK ─────────────────────────────────────────────────\r\nvar float SProximal__ = 0.0\r\nvar float SDistal__ = 0.0\r\nif RefineType__ == 'Defensive'\r\n    float sratio__ = SDA__ - SPA__ >= ATR__ * 3 ? 0.7 : SDA__ - SPA__ >= ATR__ * 2 ? 0.6 : SDA__ - SPA__ >= ATR__ * 1.6 ? 0.5 : SDA__ - SPA__ > ATR__ ? 0.25 : 0.0\r\n    SDistal__ := SDA__\r\n    SProximal__ := sratio__ == 0.0 ? SPA__ : SPA__ + (SDA__ - SPA__) * sratio__\r\n    SProximal__\r\nelse\r\n    SDistal__ := SDA__\r\n    SProximal__ := SPA__\r\n    SProximal__\r\n\r\n\r\n// ─── SUPPLY ZONE COORDINATES ─────────────────────────────────────────────────\r\nvar float YSp12__ = 0.0 // proximal price (bottom)\r\nvar float YSd12__ = 0.0 // distal  price (top)\r\nvar int XSp1__ = 0\r\nvar int XSd1__ = 0\r\nvar int XSp2__ = 0\r\n\r\n\r\nif Supply_OB_Condition__\r\n    SupplyCheck__ := bar_index_Supply_OB__\r\n    YSp12__ := OBRefine__ == 'On' ? SProximal__ : low[bar_index - bar_index_Supply_OB__]\r\n    YSd12__ := OBRefine__ == 'On' ? SDistal__ : high[bar_index - bar_index_Supply_OB__]\r\n    XSp1__ := bar_index_Supply_OB__\r\n    XSd1__ := bar_index_Supply_OB__\r\n    XSp2__ := bar_index_Supply_OB__ + 1\r\n    XSp2__\r\n\r\n\r\n// ─── SUPPLY OB DRAWING (red) ─────────────────────────────────────────────────\r\nvar bool SupCheck__ = true\r\nvar int SupCounter__ = 1\r\nvar line SLineDistal__ = na\r\nvar line SLineProximal__ = na\r\nvar line SLine50per__ = na\r\nvar box supBox__ = na\r\n\r\n\r\nif Supply_OB_Condition__\r\n    SLineDistal__ := line.new(XSd1__, YSd12__, XSp2__, YSd12__, color = #FF1744, style = line.style_solid, width = OBLineWidth__)\r\n    SLineProximal__ := line.new(XSp1__, YSp12__, XSp2__, YSp12__, color = #FF1744, style = line.style_solid, width = OBLineWidth__)\r\n    SLine50per__ := line.new(XSp1__, (YSp12__ + YSd12__) / 2, XSp2__, (YSp12__ + YSd12__) / 2, color = #FF1744, style = line.style_dotted, width = OBLineWidth__)\r\n    supBox__ := box.new(XSp1__, math.max(YSd12__, YSp12__), XSp2__, math.min(YSd12__, YSp12__), bgcolor = color.new(#FF1744, 88), border_color = color.new(#FF1744, 100), border_width = 0, text = '', text_size = size.small, text_color = color.white, text_halign = text.align_right)\r\n    SupCounter__ := 1\r\n    SupCheck__ := true\r\n    SupCheck__\r\n\r\n\r\nif (high < YSp12__ or XSd1__ == YSp12__[1]) and SupCheck__ == true and not na(SLineDistal__)\r\n    SupCounter__ := SupCounter__ + 1\r\n    line.set_x2(SLineDistal__, bar_index + 1)\r\n    line.set_x2(SLineProximal__, bar_index + 1)\r\n    line.set_x2(SLine50per__, bar_index + 1)\r\n    if not na(supBox__)\r\n        box.set_right(supBox__, bar_index + 1)\r\n\r\n\r\nif high > YSd12__ and high[1] < YSd12__\r\n    SupCheck__ := false\r\n    SupCheck__\r\n\r\n\r\n// ─── DATA WINDOW OUTPUTS ─────────────────────────────────────────────────────\r\nplot(YDd12__, title = 'Distal_Value', color = color.rgb(41, 98, 255), linewidth = 1, style = plot.style_line, display = display.data_window)\r\nplot(year(time[math.max(0, bar_index - XDd1__)]) * 10000 + month(time[math.max(0, bar_index - XDd1__)]) * 100 + dayofmonth(time[math.max(0, bar_index - XDd1__)]), title = 'Distal_StartDate', display = display.data_window)\r\n\r\nplot(YSd12__, title = 'Supply_Distal_Value', color = color.rgb(255, 23, 68), linewidth = 1, style = plot.style_line, display = display.data_window)\r\nplot(year(time[math.max(0, bar_index - XSd1__)]) * 10000 + month(time[math.max(0, bar_index - XSd1__)]) * 100 + dayofmonth(time[math.max(0, bar_index - XSd1__)]), title = 'Supply_Distal_StartDate', display = display.data_window)\r\n\r\nplot(YDd12__ > 0 and DemCheck__ ? YDd12__ : na, title = 'TradingFinder Demand', color = #2962FF, linewidth = 2, style = plot.style_linebr, display = display.data_window)\r\nplot(YSd12__ > 0 and SupCheck__ ? YSd12__ : na, title = 'TradingFinder Supply', color = #FF1744, linewidth = 2, style = plot.style_linebr, display = display.data_window)\r\n\r\n\r\n// new indicator: trend magic: KIVANCOZBILGIC\r\n// period_trend_magic_kivan = input(20, 'CCI period')\r\n// coeff_trend_magic_kivan = input(1, 'ATR Multiplier')\r\n// AP_trend_magic_kivan = input(5, 'ATR Period')\r\n// ATR_trend_magic_kivan = ta.sma(ta.tr, AP_trend_magic_kivan)\r\n// src_trend_magic_kivan = input(close)\r\n// upT_trend_magic_kivan = low - ATR_trend_magic_kivan * coeff_trend_magic_kivan\r\n// downT_trend_magic_kivan = high + ATR_trend_magic_kivan * coeff_trend_magic_kivan\r\n// MagicTrend_trend_magic_kivan = 0.0\r\n// MagicTrend_trend_magic_kivan := ta.cci(src_trend_magic_kivan, period_trend_magic_kivan) >= 0 ? upT_trend_magic_kivan < nz(MagicTrend_trend_magic_kivan[1]) ? nz(MagicTrend_trend_magic_kivan[1]) : upT_trend_magic_kivan : downT_trend_magic_kivan > nz(MagicTrend_trend_magic_kivan[1]) ? nz(MagicTrend_trend_magic_kivan[1]) : downT_trend_magic_kivan\r\n// color1_trend_magic_kivan = ta.cci(src_trend_magic_kivan, period_trend_magic_kivan) >= 0 ? #0097A7 : #801922\r\n// plot(MagicTrend_trend_magic_kivan, color = color1_trend_magic_kivan, linewidth = 10)\r\n\r\n// NEW indicator: VPVR : Fr3d0's Volume Profile Visible Range\r\n\r\nLINE_COLOR_VPVR = color.rgb(255, 97, 255)\r\n\r\nPOC_LINE_COLOR_VPVR = color.rgb(255, 97, 255)\r\n\r\nVALUE_AREA_LINE_COLOR_VPVR = color.rgb(255, 97, 255, 34)\r\n\r\nBUY_COLOR_VPVR = color.new(color.green, 50)\r\n\r\nSELL_COLOR_VPVR = color.new(color.red, 50)\r\n\r\nMAX_BARS_VPVR = 365\r\n\r\n\r\n\r\ntopBottomLineColor_VPVR = input.color(LINE_COLOR_VPVR, \"Top/bottom Line Color\")\r\n\r\npocLineColor_VPVR = input.color(POC_LINE_COLOR_VPVR, \"Point of Control Line Color\")\r\n\r\nvalueAreaLineColor_VPVR = input.color(VALUE_AREA_LINE_COLOR_VPVR, \"Value Area Line Color\")\r\n\r\nbuyBarColor_VPVR = input.color(BUY_COLOR_VPVR, \"Buy Bar Color\")\r\n\r\nsellBarColor_VPVR = input.color(SELL_COLOR_VPVR, \"Sell Bar Color\")\r\n\r\nnumOfBars_VPVR = input.int(50, 'Number of bars', minval=21, maxval=MAX_BARS_VPVR)\r\n\r\ndistLastCandle_VPVR = input.int(2, 'Distance from last candle', minval=1, maxval=MAX_BARS_VPVR)\r\n\r\nnumOfProfiles_VPVR = input.int(3, 'Number of profiles', minval=1, maxval=10)\r\n\r\nnumOfHists_VPVR = input.int(50, 'Number of hists', minval=20, maxval=100)\r\n\r\n\r\n\r\n// Clean up drawings every tick\r\n\r\nMAX_BOXES_LIMIT_VPVR = 500\r\n\r\nMAX_BOXES_VPVR = numOfProfiles_VPVR * numOfHists_VPVR\r\n\r\nexpectedBoxes_VPVR = MAX_BOXES_VPVR * 2\r\n\r\n\r\n\r\nvar buyBars_VPVR = array.new_box(MAX_BOXES_VPVR, na)\r\n\r\nfor i_VPVR=0 to MAX_BOXES_VPVR-1\r\n\r\n    box.delete(array.get(buyBars_VPVR, i_VPVR))\r\n\r\n\r\n\r\nvar sellBars_VPVR = array.new_box(MAX_BOXES_VPVR, na)\r\n\r\nfor i_VPVR=0 to MAX_BOXES_VPVR-1\r\n\r\n    box.delete(array.get(sellBars_VPVR, i_VPVR))\r\n\r\n\r\n\r\nvar topLines_VPVR = array.new_line(numOfProfiles_VPVR)\r\n\r\nvar bottomLines_VPVR = array.new_line(numOfProfiles_VPVR)\r\n\r\nvar pocLines_VPVR = array.new_line(numOfProfiles_VPVR)\r\n\r\nvar vahLines_VPVR = array.new_line(numOfProfiles_VPVR)\r\n\r\nvar valLines_VPVR = array.new_line(numOfProfiles_VPVR)\r\n\r\nfor i_VPVR=0 to numOfProfiles_VPVR - 1\r\n\r\n    line.delete(array.get(topLines_VPVR, i_VPVR))\r\n\r\n    line.delete(array.get(bottomLines_VPVR, i_VPVR))\r\n\r\n    line.delete(array.get(pocLines_VPVR, i_VPVR))\r\n\r\n    line.delete(array.get(vahLines_VPVR, i_VPVR))\r\n\r\n    line.delete(array.get(valLines_VPVR, i_VPVR))\r\n\r\n\r\n\r\nvar label boxWarning_VPVR = na\r\n\r\n\r\n\r\nif barstate.islast\r\n\r\n    if expectedBoxes_VPVR > MAX_BOXES_LIMIT_VPVR\r\n\r\n        label.delete(boxWarning_VPVR)\r\n\r\n        boxWarning_VPVR := label.new(\r\n\r\n            x=bar_index,\r\n\r\n            y=high,\r\n\r\n            text=\"⚠ VPVR WARNING\\nBoxes requested: \" + str.tostring(expectedBoxes_VPVR) +\r\n\r\n                 \"\\nMax allowed: \" + str.tostring(MAX_BOXES_LIMIT_VPVR),\r\n\r\n            style=label.style_label_down,\r\n\r\n            color=color.new(color.red, 0),\r\n\r\n            textcolor=color.white,\r\n\r\n            size=size.small\r\n\r\n        )\r\n\r\n    else\r\n\r\n        label.delete(boxWarning_VPVR)\r\n\r\n   \r\n\r\n    for k_VPVR = 0 to numOfProfiles_VPVR - 1\r\n\r\n        offset_VPVR = k_VPVR * (numOfBars_VPVR - 1)\r\n\r\n        lastBar_VPVR = bar_index - distLastCandle_VPVR - offset_VPVR\r\n\r\n        firstBar_VPVR = lastBar_VPVR - numOfBars_VPVR + 1\r\n\r\n        visibleBars_VPVR = lastBar_VPVR - firstBar_VPVR + 1\r\n\r\n        widestHistWidth_VPVR = visibleBars_VPVR\r\n\r\n\r\n\r\n        histLowList_VPVR = array.new_float(numOfHists_VPVR, na)\r\n\r\n        histHighList_VPVR = array.new_float(numOfHists_VPVR, na)\r\n\r\n        histPriceList_VPVR = array.new_float(numOfHists_VPVR, 0.0)\r\n\r\n\r\n\r\n        histBuyVolumeList_VPVR = array.new_float(numOfHists_VPVR, 0.0)\r\n\r\n        histSellVolumeList_VPVR = array.new_float(numOfHists_VPVR, 0.0)\r\n\r\n        histVolumePercentageList_VPVR = array.new_float(numOfHists_VPVR, 0.0)\r\n\r\n\r\n\r\n        totalVolume_VPVR = 0.0\r\n\r\n        volumeAccum_VPVR = 0.0\r\n\r\n        float VAH_VPVR = na\r\n\r\n        float VAL_VPVR = na\r\n\r\n        float rangeHigh_VPVR = na\r\n\r\n        float rangeLow_VPVR = na\r\n\r\n        float rangeHeight_VPVR = na\r\n\r\n        float histHeight_VPVR = na\r\n\r\n\r\n\r\n        // Define range height\r\n\r\n        rangeHigh_VPVR := high[offset_VPVR + distLastCandle_VPVR]\r\n\r\n        rangeLow_VPVR  := low[offset_VPVR + distLastCandle_VPVR]\r\n\r\n        for _i_VPVR = 1 to numOfBars_VPVR - 1\r\n\r\n            i_VPVR = offset_VPVR + distLastCandle_VPVR + _i_VPVR\r\n\r\n            rangeHigh_VPVR := math.max(rangeHigh_VPVR, high[i_VPVR])\r\n\r\n            rangeLow_VPVR  := math.min(rangeLow_VPVR, low[i_VPVR])\r\n\r\n        rangeHeight_VPVR := rangeHigh_VPVR - rangeLow_VPVR\r\n\r\n        histHeight_VPVR := rangeHeight_VPVR / numOfHists_VPVR\r\n\r\n\r\n\r\n        // Draw top and bottom of the range considered\r\n\r\n        array.set(topLines_VPVR, k_VPVR, line.new(firstBar_VPVR, rangeHigh_VPVR, lastBar_VPVR, rangeHigh_VPVR, xloc=xloc.bar_index, color=topBottomLineColor_VPVR, width = 5))\r\n\r\n        array.set(bottomLines_VPVR, k_VPVR, line.new(firstBar_VPVR, rangeLow_VPVR, lastBar_VPVR, rangeLow_VPVR, xloc=xloc.bar_index, color=topBottomLineColor_VPVR, width = 6))\r\n\r\n       \r\n\r\n        // Define lows and highs of the hists\r\n\r\n        for i_VPVR = 0 to numOfHists_VPVR - 1\r\n\r\n            histLow_VPVR = rangeLow_VPVR + histHeight_VPVR * i_VPVR\r\n\r\n            histHigh_VPVR = rangeLow_VPVR + histHeight_VPVR * (i_VPVR + 1)\r\n\r\n            array.set(histLowList_VPVR, i_VPVR, histLow_VPVR)\r\n\r\n            array.set(histHighList_VPVR, i_VPVR, histHigh_VPVR)\r\n\r\n            array.set(histPriceList_VPVR, i_VPVR, (histLow_VPVR + histHigh_VPVR) / 2)\r\n\r\n           \r\n\r\n        // Assign bar's volumes to hists\r\n\r\n        for _i_VPVR = 0 to numOfBars_VPVR - 1\r\n\r\n            i_VPVR = offset_VPVR + distLastCandle_VPVR + _i_VPVR\r\n\r\n            totalVolume_VPVR := totalVolume_VPVR + volume[i_VPVR]\r\n\r\n            currentBarHeight_VPVR = high[i_VPVR] - low[i_VPVR]\r\n\r\n            currentBuyVolume_VPVR = (high[i_VPVR] == low[i_VPVR]) ? 0 : volume[i_VPVR] * (close[i_VPVR] - low[i_VPVR]) / currentBarHeight_VPVR\r\n\r\n            currentSellVolume_VPVR = (high[i_VPVR] == low[i_VPVR]) ? 0 : volume[i_VPVR] * (high[i_VPVR] - close[i_VPVR]) / currentBarHeight_VPVR\r\n\r\n\r\n\r\n            // Define the percentages of the current volume to give to hists\r\n\r\n            for j_VPVR = 0 to numOfHists_VPVR - 1\r\n\r\n                histLow_VPVR = array.get(histLowList_VPVR, j_VPVR)\r\n\r\n                histHigh_VPVR = array.get(histHighList_VPVR, j_VPVR)\r\n\r\n                target_VPVR = (math.max(histHigh_VPVR, high[i_VPVR]) - math.min(histLow_VPVR, low[i_VPVR]))\r\n\r\n                 - (math.max(histHigh_VPVR, high[i_VPVR]) - math.min(histHigh_VPVR, high[i_VPVR]))\r\n\r\n                 - (math.max(histLow_VPVR, low[i_VPVR]) - math.min(histLow_VPVR, low[i_VPVR]))\r\n\r\n                histVolumePercentage_VPVR = target_VPVR / currentBarHeight_VPVR\r\n\r\n               \r\n\r\n                histBuyVolume_VPVR = array.get(histBuyVolumeList_VPVR, j_VPVR)\r\n\r\n                histSellVolume_VPVR = array.get(histSellVolumeList_VPVR, j_VPVR)\r\n\r\n               \r\n\r\n                // If there is at least one hist affected\r\n\r\n                // then divide the current volume by the number of hists affected\r\n\r\n                if histVolumePercentage_VPVR > 0\r\n\r\n                    array.set(histBuyVolumeList_VPVR, j_VPVR, histBuyVolume_VPVR + currentBuyVolume_VPVR * histVolumePercentage_VPVR)\r\n\r\n                    array.set(histSellVolumeList_VPVR, j_VPVR, histSellVolume_VPVR + currentSellVolume_VPVR * histVolumePercentage_VPVR)\r\n\r\n       \r\n\r\n        // Find the hist with the highest volume\r\n\r\n        highestHistVolume_VPVR = 0.0\r\n\r\n        pocIndex_VPVR = 0\r\n\r\n        for i_VPVR = 0 to numOfHists_VPVR - 1\r\n\r\n            histBuyVolume_VPVR = array.get(histBuyVolumeList_VPVR, i_VPVR)\r\n\r\n            histSellVolume_VPVR = array.get(histSellVolumeList_VPVR, i_VPVR)\r\n\r\n            histVolume_VPVR = histBuyVolume_VPVR + histSellVolume_VPVR\r\n\r\n            if histVolume_VPVR > highestHistVolume_VPVR\r\n\r\n                highestHistVolume_VPVR := histVolume_VPVR\r\n\r\n                pocIndex_VPVR := i_VPVR\r\n\r\n\r\n\r\n        // Draw Point of Control\r\n\r\n        pocHistLow_VPVR = array.get(histLowList_VPVR, pocIndex_VPVR)\r\n\r\n        pocHistHigh_VPVR = array.get(histHighList_VPVR, pocIndex_VPVR)\r\n\r\n        pocPos_VPVR = pocHistLow_VPVR + (pocHistHigh_VPVR - pocHistLow_VPVR) / 2\r\n\r\n        array.set(pocLines_VPVR, k_VPVR, line.new(firstBar_VPVR, pocPos_VPVR, lastBar_VPVR, pocPos_VPVR, xloc=xloc.bar_index, color=pocLineColor_VPVR, width = 20))  \r\n\r\n   \r\n\r\n        // Value area calculation\r\n\r\n        valueAreaVolume_VPVR  = totalVolume_VPVR * 0.7\r\n\r\n        volumeAccum_VPVR := array.get(histBuyVolumeList_VPVR, pocIndex_VPVR) + array.get(histSellVolumeList_VPVR, pocIndex_VPVR)\r\n\r\n        VAH_VPVR := pocPos_VPVR\r\n\r\n        VAL_VPVR := pocPos_VPVR\r\n\r\n\r\n\r\n        upIndex_VPVR = pocIndex_VPVR + 1\r\n\r\n        downIndex_VPVR = pocIndex_VPVR - 1\r\n\r\n        for __VPVR = 0 to numOfHists_VPVR - 1\r\n\r\n            volUp_VPVR = (upIndex_VPVR < numOfHists_VPVR) ? (array.get(histBuyVolumeList_VPVR, upIndex_VPVR) + array.get(histSellVolumeList_VPVR, upIndex_VPVR)) : 0.0\r\n\r\n            volDown_VPVR = (downIndex_VPVR >= 0) ? (array.get(histBuyVolumeList_VPVR, downIndex_VPVR) + array.get(histSellVolumeList_VPVR, downIndex_VPVR)) : 0.0\r\n\r\n\r\n\r\n            if volumeAccum_VPVR >= valueAreaVolume_VPVR\r\n\r\n                break\r\n\r\n\r\n\r\n            canGoUp_VPVR = upIndex_VPVR < numOfHists_VPVR\r\n\r\n            canGoDown_VPVR = downIndex_VPVR >= 0\r\n\r\n\r\n\r\n            if not canGoUp_VPVR and not canGoDown_VPVR\r\n\r\n                break\r\n\r\n\r\n\r\n            if canGoUp_VPVR and (not canGoDown_VPVR or volUp_VPVR >= volDown_VPVR)\r\n\r\n                VAH_VPVR := array.get(histPriceList_VPVR, upIndex_VPVR)\r\n\r\n                volumeAccum_VPVR += volUp_VPVR\r\n\r\n                upIndex_VPVR += 1\r\n\r\n            else\r\n\r\n                VAL_VPVR := array.get(histPriceList_VPVR, downIndex_VPVR)\r\n\r\n                volumeAccum_VPVR += volDown_VPVR\r\n\r\n                downIndex_VPVR -= 1\r\n\r\n\r\n\r\n        array.set(vahLines_VPVR, k_VPVR, line.new(firstBar_VPVR, VAH_VPVR, lastBar_VPVR, VAH_VPVR, color=valueAreaLineColor_VPVR, width=8, style=line.style_solid))\r\n\r\n        array.set(valLines_VPVR, k_VPVR, line.new(firstBar_VPVR, VAL_VPVR, lastBar_VPVR, VAL_VPVR, color=valueAreaLineColor_VPVR, width=8, style=line.style_solid))\r\n\r\n\r\n\r\n        // Draw hists and highlight the Point of Control\r\n\r\n        for i_VPVR = 0 to numOfHists_VPVR - 1\r\n\r\n            histLow_VPVR = array.get(histLowList_VPVR, i_VPVR)\r\n\r\n            histHigh_VPVR = array.get(histHighList_VPVR, i_VPVR)\r\n\r\n            histBuyVolume_VPVR = array.get(histBuyVolumeList_VPVR, i_VPVR)\r\n\r\n            histSellVolume_VPVR = array.get(histSellVolumeList_VPVR, i_VPVR)\r\n\r\n            histVolume_VPVR = histBuyVolume_VPVR + histSellVolume_VPVR\r\n\r\n\r\n\r\n            histWidth_VPVR = 0.0\r\n\r\n            if highestHistVolume_VPVR > 0\r\n\r\n                histWidth_VPVR := histVolume_VPVR / highestHistVolume_VPVR * widestHistWidth_VPVR\r\n\r\n           \r\n\r\n            histBuyWidth_VPVR = 0.0\r\n\r\n            histSellWidth_VPVR = 0.0\r\n\r\n            if histVolume_VPVR > 0\r\n\r\n                histBuyWidth_VPVR := histBuyVolume_VPVR / histVolume_VPVR * histWidth_VPVR\r\n\r\n                histSellWidth_VPVR := histSellVolume_VPVR / histVolume_VPVR * histWidth_VPVR\r\n\r\n\r\n\r\n            // Draw buy and sell hists\r\n\r\n            boxIndex_VPVR = k_VPVR * numOfHists_VPVR + i_VPVR\r\n\r\n            buyHistEnd_VPVR = int(firstBar_VPVR + histBuyWidth_VPVR)\r\n\r\n            sellHistEnd_VPVR = int(buyHistEnd_VPVR + histSellWidth_VPVR)\r\n\r\n            buyBox_VPVR = box.new(left=firstBar_VPVR, top=histHigh_VPVR, right=buyHistEnd_VPVR, bottom=histLow_VPVR, bgcolor=buyBarColor_VPVR, border_width=0)\r\n\r\n            array.set(buyBars_VPVR, boxIndex_VPVR, buyBox_VPVR)\r\n\r\n            sellBox_VPVR = box.new(left=buyHistEnd_VPVR, top=histHigh_VPVR, right=sellHistEnd_VPVR, bottom=histLow_VPVR, bgcolor=sellBarColor_VPVR, border_width=0)\r\n\r\n            array.set(sellBars_VPVR, boxIndex_VPVR, sellBox_VPVR) ";
